import ast
import json
import re

_TYPE_MAP = {"integer": "int", "number": "float", "string": "str", "boolean": "bool"}


def parse_openapi(spec) -> dict:
    """OpenAPI dict -> {operationId: {params: {name: type},
    required: [names], returns: type}}. Raises on non-dict input."""
    if isinstance(spec, str):
        spec = json.loads(spec)
    if not isinstance(spec, dict) or "paths" not in spec:
        raise ValueError("apicontract: not an OpenAPI document")
    out = {}
    for path, methods in spec.get("paths", {}).items():
        for method, op in (methods or {}).items():
            if not isinstance(op, dict):
                continue
            oid = op.get("operationId") or f"{method.upper()} {path}"
            params = {}
            required = []
            for prm in op.get("parameters", []) or []:
                sch = prm.get("schema", {})
                t = _TYPE_MAP.get(sch.get("type"), sch.get("type", "?"))
                params[prm["name"]] = t
                if prm.get("required"):
                    required.append(prm["name"])
            ret = "?"
            resp = (op.get("responses", {}) or {}).get("200", {})

            content = (resp.get("content", {}) or {}).get("application/json", {})
            sch = content.get("schema", {}) or {}
            if "$ref" in sch:
                ret = sch["$ref"].split("/")[-1]
            elif sch.get("type"):
                ret = _TYPE_MAP.get(sch["type"], sch["type"])
            out[oid] = {"params": params, "required": required, "returns": ret}
    return out


def check_python_server(src, spec) -> list:
    """Drift items between the schema and the Python implementation.

    A server op is a top-level def named like the operationId; parameter
    names and annotations are compared. Missing ops are drift."""
    contract = parse_openapi(spec)
    tree = ast.parse(src)
    fns = {}
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            args = [a.arg for a in node.args.args]
            anns = {a.arg: (ast.unparse(a.annotation) if a.annotation else None)
                    for a in node.args.args}
            ret = ast.unparse(node.returns) if node.returns else None
            fns[node.name] = {"args": args, "anns": anns, "returns": ret}
    drift = []
    for oid, c in contract.items():
        if oid not in fns:
            drift.append({"op": oid, "kind": "missing-endpoint",
                          "side": "python-server"})
            continue
        f = fns[oid]
        for p, t in c["params"].items():
            if p not in f["args"]:
                drift.append({"op": oid, "kind": "missing-param",
                              "param": p, "side": "python-server"})
            else:
                ann = f["anns"].get(p)
                if ann and ann not in (t, f"{t} | None"):
                    drift.append({"op": oid, "kind": "type-mismatch",

                                  "param": p, "schema": t, "code": ann,
                                  "side": "python-server"})
        for p in c["required"]:
            if p not in f["args"]:
                drift.append({"op": oid, "kind": "missing-required",
                              "param": p, "side": "python-server"})
    return drift


_GO_FN = re.compile(r"func\s+(?:\(\w+\s+[*\w.]+\)\s+)?(\w+)\s*"
                    r"\(([^)]*)\)\s*([*\w.]+)?")


def check_go_client(src, spec) -> list:
    """Drift items between the schema and the Go client.

    Client ops are funcs named like operationId; Go types map:
    int->int, string->str, float64->float, bool->bool."""
    contract = parse_openapi(spec)
    go_map = {"int": "int", "string": "str", "float64": "float",
              "bool": "bool", "int64": "int"}
    fns = {}
    for m in _GO_FN.finditer(src):
        name, params_raw, ret = m.group(1), m.group(2) or "", m.group(3)
        params = {}
        for part in params_raw.split(","):
            part = part.strip()
            if not part:
                continue
            bits = part.split()
            if len(bits) == 2:
                params[bits[0]] = go_map.get(bits[1], bits[1])
        fns[name] = {"params": params,
                     "returns": go_map.get(ret, ret) if ret else None}
    drift = []
    for oid, c in contract.items():
        if oid not in fns:
            drift.append({"op": oid, "kind": "missing-endpoint",
                          "side": "go-client"})
            continue

        f = fns[oid]
        for p, t in c["params"].items():
            if p not in f["params"]:
                drift.append({"op": oid, "kind": "missing-param",
                              "param": p, "side": "go-client"})
            elif f["params"][p] != t:
                drift.append({"op": oid, "kind": "type-mismatch",
                              "param": p, "schema": t, "code": f["params"][p],
                              "side": "go-client"})
    return drift


def agreement(server_src, client_src, spec) -> dict:
    """Full cross-language agreement: BOTH sides checked against the schema.

    Verdict: agree only when both drift lists are empty. Every drift item
    names the side, the op, and the kind -- nothing is silently patched."""
    s = check_python_server(server_src, spec)
    g = check_go_client(client_src, spec)
    return {"agree": not s and not g,
            "drift": sorted(s + g, key=lambda d: (d["op"], d["side"]))}

"""
assign

Assignment rendering + init extraction — feeds closed-form loop sums."""
from __future__ import annotations

import re

from .peg import Node

_AUG = re.compile(r"^([A-Za-z_]\w*)\s*(\+=|-=|\*=|/=)\s*(.+)$")
_INIT = re.compile(r"^([A-Za-z_]\w*)\s*=\s*(-?\d+)$")


def render_assignment(node: Node, src: str) -> str:
    """'s += i' -> canonical 's = s + i'."""
    txt = src[node.pos:node.endpos].strip()
    if (m := _AUG.match(txt)):
        var, op, rhs = m.groups()
        return f"{var} = {var} {op[0]} {rhs.strip()}"
    return txt


def numeric_inits(tree, src: str) -> dict[str, int]:
    """Implement numeric inits with the module's explicit API and failure semantics."""
    inits: dict[str, int] = {}

    def walk(n):
        """Implement walk with the module's explicit API and failure semantics."""
        if isinstance(n, Node):
            if n.tag == "assignment":
                txt = src[n.pos:n.endpos].strip()
                if (m := _INIT.match(txt)):
                    inits.setdefault(m.group(1), int(m.group(2)))
            for c in n.children:
                walk(c)
        elif isinstance(n, list):
            for c in n:
                walk(c)
    walk(tree)

    return inits


def loop_assignments(while_node: Node, src: str) -> list[str]:
    """Implement loop assignments with the module's explicit API and failure semantics."""
    out: list[str] = []

    def walk(n):
        """Implement walk with the module's explicit API and failure semantics."""
        if isinstance(n, Node):
            if n.tag in ("assignment", "augmented_assignment"):
                out.append(render_assignment(n, src))
                return
            for c in n.children:
                walk(c)
        elif isinstance(n, list):
            for c in n:
                walk(c)

    kids = [c for c in while_node.children if isinstance(c, Node)]
    body = next((k for k in kids if k.tag in ("block", "statement_list")),
                kids[1] if len(kids) >= 2 else None)
    if body is not None:
        walk(body)
    return out

"""Continuous claim/evidence graph with exact upstream invalidation identities."""
from __future__ import annotations

import hashlib
import json

SCHEMA = "pegrex.continuous-assurance-graph.v1"
_KINDS = {"api-contract", "access-policy", "taint-invariant", "migration-property"}


def _identity(value) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def build_assurance_graph(claims) -> dict:
    """Build nodes from claims and evidence edges pinned to upstream content."""
    nodes, edges, unknowns = [], [], []
    seen = set()
    try:
        for claim in claims:
            identifier = claim["id"]
            if not identifier or identifier in seen:
                raise ValueError("claim IDs must be nonempty and unique")
            seen.add(identifier)
            kind = claim["kind"]
            if kind not in _KINDS:
                raise ValueError(f"unsupported claim kind: {kind}")
            verdict = claim.get("verdict", "unknown")
            if verdict not in {"proved", "refuted", "unknown"}:
                verdict = "unknown"
                unknowns.append(f"{identifier}:invalid claim verdict normalized to UNKNOWN")
            evidence_rows = claim.get("evidence") or []
            if verdict == "proved" and not evidence_rows:
                verdict = "unknown"
                unknowns.append(f"{identifier}:proof claim has no evidence")
            node = {"id": identifier, "kind": kind, "verdict": verdict,
                    "statement": claim.get("statement"),
                    "evidence": [], "unknowns": list(claim.get("unknowns") or [])}
            if node["unknowns"] and verdict == "proved":
                node["verdict"] = "unknown"

