def verify_report(html_text, key) -> dict:
    """Re-authenticate an emitted report: extract the embedded envelope,
    re-hash the manifest, and check the HMAC signature."""
    from .attest import hmac_verify
    start = html_text.find('id=\'pegrex-manifest\'>')
    if start < 0:
        return {"ok": False, "reason": "no embedded manifest in report"}
    start = html_text.find(">", start) + 1
    end = html_text.find("</script>", start)
    try:
        envelope = json.loads(html_text[start:end])
    except ValueError as e:
        return {"ok": False, "reason": f"embedded manifest unreadable: {e}"}
    manifest = envelope.get("manifest")
    sha = hashlib.sha256(canonical_json(manifest).encode()).hexdigest()
    if sha != envelope.get("manifest_sha256"):
        return {"ok": False, "reason": "manifest sha256 mismatch -- the "
                                         "findings were altered"}
    if not hmac_verify(manifest, key, envelope.get("signature")):
        return {"ok": False, "reason": "signature mismatch (tampered or "
                                         "wrong key)"}
    return {"ok": True, "files": len(manifest.get("files", [])),
            "findings": len(manifest.get("findings", [])),
            "manifest_sha256": sha}

def check(a_path, b_path, claim="equivalent"):
    """check(a_path, b_path, claim): see module docstring."""
    src = open(b_path, encoding="utf-8").read()
    has_sink = re.search(rf"{re.escape(sink)}\s*\(", src) is not None
    if not has_sink:
        return {"verified": True, "counterexample": None}
    guard = _disc(src, sink)
    if guard is None:
        # sink present but unguarded: worse, not fixed
        return {"verified": False,
                "counterexample": {"inputs": payload,
                                   "reason": "sink is now unguarded"}}
    still = _sp(guard)
    if still and all(still.get(k) == v for k, v in payload.items()):
        return {"verified": False,
                "counterexample": {"inputs": payload}}
    return {"verified": True, "counterexample": None}

"""
bisim

Equivalence by bisimulation: partition-refine two CFGs against labels
(constraint, result) until stable.  Certifies cross-language equivalence
without enumeration bounds — subsumes contracts in one mechanism."""

from __future__ import annotations


def _labels(cfg, cond, render, unroll=2):
    """block_id -> outgoing label multiset for refinement."""
    from pegrex.paths import PathEnumerator
    labels = {}
    paths = PathEnumerator(cfg, unroll=unroll).enumerate()
    for p in paths:
        sig = []
        for i in range(len(p) - 1):
            for dst, e in cfg.successors(p[i]):
                if dst == p[i + 1]:
                    base = e.cond[0] if isinstance(e.cond, tuple) else e.cond
                    txt = str(cond(base)) if cond else e.kind
                    sig.append((e.kind, txt))
        result = None
        for b in p:
            blk = cfg.blocks[b]
            if blk.term == "ret" and blk.stmts and render:
                result = render(blk.stmts[0])
        labels[tuple(p)] = (tuple(sorted(sig)), result)
    return labels


def bisimilar(cfg_a, cfg_b, cond_a, cond_b, render_a, render_b, unroll=2) -> bool:
    """True if the two CFGs agree on path-label multisets up to unroll."""
    la = _labels(cfg_a, cond_a, render_a, unroll)
    lb = _labels(cfg_b, cond_b, render_b, unroll)
    return sorted(la.values()) == sorted(lb.values())

    """Concrete input satisfying the guard (the payload)."""
    lb = lb or DEFAULT_LB
    try:
        atoms = atoms_of(lower_condition(guard_text))
    except Exception:
        return None
    model = lb.learn(atoms)
    if not model.feasible():
        return None
    return model.model() or None


def minimize(guard_text, payload, lb=None):
    """Drop atoms one at a time; keep a witness equal to the payload."""
    lb = lb or DEFAULT_LB
    atoms = atoms_of(lower_condition(guard_text))
    minimal = list(atoms)
    for a in list(minimal):
        trial = [x for x in minimal if x != a]
        m = lb.learn(trial)
        if m.feasible() and m.model() == payload:
            minimal = trial
    return minimal


def run(src, sink_name, lb=None, lang="python"):
    """Full chain: discover -> solve -> minimize. Unknown when any stage
    cannot proceed -- never a fake PoC."""
    guard = discover(src, sink_name, lang=lang)
    if guard is None:
        return {"status": "unknown", "reason": f"no guard found for {sink_name}"}
    payload = solve_payload(guard, lb)
    if not payload:
        return {"status": "unknown",
                "reason": "guard constraints infeasible or opaque",
                "guard": guard}
    core = minimize(guard, payload, lb)
    return {"status": "poc", "guard": guard, "payload": payload,
            "minimal_guard_atoms": core,
            "removed": len(atoms_of(lower_condition(guard))) - len(core)}

"""In-toto statements with SLSA v1 provenance and verifiable subjects."""
from __future__ import annotations
import hashlib, json, os
from pathlib import Path
SCHEMA = "https://in-toto.io/Statement/v1"
PREDICATE = "https://slsa.dev/provenance/v1"


def _paths(values):
    if isinstance(values, dict): return dict(values)
    result = {}
    for value in values or []:
        path = Path(value)
        if path.name in result: raise ValueError("subject/material names must be unique")
        result[path.name] = path
    return result

def _subjects(values):
    rows = []
    for name, path in sorted(_paths(values).items()):
        raw = Path(path).read_bytes()
        rows.append({"name": name, "digest": {"sha256": hashlib.sha256(raw).hexdigest()}})
    return rows

def create_build_provenance(subjects, *, builder_id, command_argv, build_type,
                            materials=None, internal_parameters=None) -> dict:
    """Create an unsigned local statement; builder authentication is not claimed."""
    if isinstance(command_argv, str) or not command_argv or any(not isinstance(row, str) for row in command_argv):
        raise ValueError("build command must be a nonempty argv sequence")
    subject_rows = _subjects(subjects)
    if not subject_rows: raise ValueError("at least one verifiable subject is required")
    dependencies = []
    for uri, path in sorted(_paths(materials).items()):
        raw = Path(path).read_bytes()
        dependencies.append({"uri": uri, "digest": {"sha256": hashlib.sha256(raw).hexdigest()}})
    predicate = {"buildDefinition": {"buildType": build_type,
        "externalParameters": {"command": list(command_argv)},
        "internalParameters": internal_parameters or {}, "resolvedDependencies": dependencies},
        "runDetails": {"builder": {"id": builder_id},
            "metadata": {"invocationId": "local-unauthenticated"},

            "byproducts": []}}
    return {"_type": SCHEMA, "subject": subject_rows, "predicateType": PREDICATE,
            "predicate": predicate}


def verify_build_provenance(statement, *, subject_paths=None, material_paths=None) -> dict:
    """Verify statement structure and hashes; UNSIGNED builder identity is not authenticated."""
    unknowns = []
    try:
        if statement.get("_type") != SCHEMA or statement.get("predicateType") != PREDICATE:
            return {"verified": False, "verdict": "unknown", "unknowns": ["unsupported statement"]}
        subjects = statement["subject"]
        if not isinstance(subjects, list) or not subjects: raise ValueError("subjects missing")
        paths = _paths(subject_paths if subject_paths is not None else {row["name"]: row["name"] for row in subjects})
        for row in subjects:
            name, expected = row["name"], row["digest"]["sha256"]
            if name not in paths or not Path(paths[name]).is_file():
                unknowns.append(f"subject unavailable: {name}"); continue
            actual = hashlib.sha256(Path(paths[name]).read_bytes()).hexdigest()
            if actual != expected:
                return {"verified": False, "verdict": "refuted", "subject": name,
                        "expected_sha256": expected, "actual_sha256": actual, "unknowns": unknowns}
        materials = statement["predicate"]["buildDefinition"].get("resolvedDependencies", [])
        material_paths = _paths(material_paths)
        for row in materials:
            uri = row["uri"]
            if uri not in material_paths:
                unknowns.append(f"material not reverified: {uri}"); continue
            actual = hashlib.sha256(Path(material_paths[uri]).read_bytes()).hexdigest()
            if actual != row["digest"]["sha256"]:
                return {"verified": False, "verdict": "refuted", "material": uri, "unknowns": unknowns}
        return {"verified": not unknowns, "verdict": "unknown" if unknowns else "proved",
                "subjects": len(subjects), "materials": len(materials), "unknowns": unknowns,
                "authentication": "unsigned; only structure and available subject/material hashes verified"}
    except (KeyError, TypeError, ValueError, OSError, AttributeError) as error:
        return {"verified": False, "verdict": "unknown", "unknowns": [f"malformed provenance: {error}"]}

"""
callgraph

Function-call graph extraction + visualization (DOT + ASCII).
Nodes are functions; edges are caller -> callee, resolved per scope."""

from __future__ import annotations

from dataclasses import dataclass, field

from .peg import Node


@dataclass
class CallGraph:
    """CallGraph - see module docstring."""
    functions: dict = field(default_factory=dict) # name -> {line, calls:set}
    edges: set = field(default_factory=set)       # (caller, callee)

    def to_dot(self) -> str:
        """Implement to dot with the module's explicit API and failure semantics."""
        lines = ["digraph callgraph {", "  rankdir=LR;",
                 '  node [shape=box, style=rounded];']
        for name in sorted(self.functions):
            lines.append(f'  "{name}";')
        for caller, callee in sorted(self.edges):
            lines.append(f'  "{caller}" -> "{callee}";')
        lines.append("}")
        return chr(10).join(lines)

    def to_ascii(self) -> str:
        """Implement to ascii with the module's explicit API and failure semantics."""
        out = []
        for name in sorted(self.functions):
            callees = sorted(c for a, c in self.edges if a == name)
            mark = " -> " + ", ".join(callees) if callees else " (leaf)"
            out.append(f"{name}{mark}")
        return chr(10).join(out)

def build_call_graph(source: str, lang: str = "python",
                     all_functions: bool = True, *, tree=None) -> CallGraph:
    """Extract the call graph from source.  Per-function bodies are walked;
    call nodes resolve to callee names (unresolved callees become '?'-free
    external nodes when external=True)."""
    import sys as _sys
    root = _sys.path and None
    import pipeline
    from .languages import normalize_language, get_language
    normalized = normalize_language(lang)
    if normalized is None:
        raise ValueError(f"unsupported call-graph language {lang!r}")
    spec = get_language(normalized)
    if "callgraph" not in spec.capabilities:
        raise NotImplementedError(f"call graph unsupported for {normalized}: {spec.notes}")
    if normalized == "python":
        bodies = pipeline.python_functions(source, tree=tree)
        call_tags = {"call", "call_expression"}
    else:
        if tree is None:
            parse, tags, mk = pipeline.frontend_for(normalized)
            tree = parse(source)
        bodies = {"": tree}
        call_tags = {"call_expression", "call"}

    g = CallGraph()
    fn_names = set(bodies.keys()) if lang == "python" else set()
    if not fn_names:
        fn_names = set(bodies.keys())

    for fname, body in bodies.items():
        line = 0
        g.functions.setdefault(fname, {"line": line, "calls": set()})
        stack = [body]
        while stack:
            n = stack.pop()
            if isinstance(n, Node):
                if n.tag in call_tags:
                    callee = _callee_name(n, source)
                    if callee:

                        g.functions[fname]["calls"].add(callee)
                        g.edges.add((fname, callee))
                stack.extend(c for c in n.children
                             if isinstance(c, Node))
            elif isinstance(n, list):
                stack.extend(c for c in n if isinstance(c, Node))
    return g


def _callee_name(call_node: Node, source: str) -> str:
    """First identifier-ish child of the call = the callee name."""
    for c in call_node.children:
        if isinstance(c, str):
            return c.split("(")[0].strip() or ""
        if isinstance(c, Node):
            if c.tag in ("identifier", "attribute", "expression",
                         "field_expression", "call_expression"):
                txt = source[c.pos:c.endpos].strip()
                return txt.split("(")[0].split(".")[-1].strip() or ""
            txt = source[c.pos:c.endpos].strip()
            if txt and (txt[0].isalpha() or txt[0] == "_"):
                return txt.split("(")[0].split(".")[-1].strip()
    return ""

def rec(n, path, visits):
    """Implement rec with the module's explicit API and failure semantics."""
    if not isinstance(n, Node):
        return
    if n.tag in CFGBuilder._TRANSPARENT:
        acc = [block()]
        for ch in n.children:
            if isinstance(ch, Node):
                yield from rec(ch, path + acc, visits)
        return
    tag = n.tag
    kids = [x for x in n.children if isinstance(x, Node)]
    if tag == spec.return_:
        yield path + [block()]
        return
    if tag == spec.break_:
        yield path + [("break",)]
        return
    if tag == spec.block:
        acc = [block()]
        for ch in kids:
            yield from rec(ch, path + acc, visits)
        return
    if tag == spec.if_ or (callable(spec.if_)
                           and tag == getattr(spec.if_, "_tag", None)):
        cond, then, els = spec.if_parts(n)
        yield from rec(then, path + [block()], visits)
        if els is not None:
            yield from rec(els, path + [block()], visits)
        else:
            yield path + [block()]
        return
    if tag == spec.while_ or (callable(spec.while_)
                              and tag == getattr(spec.while_, "_tag", None)):
        cond, body = spec.while_parts(n)
        head = block()
        yield path + [head]
        key = id(n)
        if visits.get(key, 0) < unroll:
            yield from rec(body, path + [head, block()],
                           {**visits, key: visits.get(key, 0) + 1})
        return
    if tag == spec.for_ or (callable(spec.for_)
                            and tag == getattr(spec.for_, "_tag", None)):
        cond, body = spec.for_parts(n)
        head = block()
        yield path + [head] # zero-iteration path
        key = id(n)
        if visits.get(key, 0) < unroll:
            yield from rec(body, path + [head, block()],
                           {**visits, key: visits.get(key, 0) + 1})
        return
    yield path + [block()]

use_sandbox=False (default): candidates execute in-process (fast; the
