        env[st[2]] = Op("+", (env.get(st[2], V(st[2])), aug))
    elif op == "sub":
        aug = _expr(st[1], env)
        env[st[2]] = Op("-", (env.get(st[2], V(st[2])), aug))
    elif op == "call":
