def saturated(self, rules) -> bool:
    """Apply rules until none fire. Returns True if fixed point."""
    changed = True
    while changed:
        changed = False
        for lhs_pat, rhs_pat in rules:
            for i, n in enumerate(self.nodes):
                if self.find(i) != i:
                    continue
                m = self._match(lhs_pat, n)
                if m is not None:
                    r = self._build(rhs_pat, m)
                    if self.find(r) != self.find(i):
                        self.union(i, r)
                        changed = True
    return True

def _match(self, pat, node):
    if isinstance(pat, int):
        return {pat: node.value} if node.op == "lit" else None
    op, *sub = pat
    if node.op != op:
        return None
    out = {}
    for p, a in zip(sub, node.args):
        m = self._match(p, self.nodes[a])
        if m is None:
            return None
        out.update(m)
    return out

def _build(self, pat, m):
    if isinstance(pat, int):
        return self.add("lit", (), m[pat])
    op, *sub = pat
    return self.add(op, tuple(self._build(p, m) for p in sub))

def extract(self, i: int, cost=lambda n: 1) -> object:
    """Cheapest representative expression."""
    root = self.find(i)
    best, bestc = None, float("inf")
    for j, n in enumerate(self.nodes):
        if self.find(j) == root:
            c = cost(n)
            if c < bestc:
                best, bestc = n, c
    if best is None:
        return None
    if best.op == "lit":
        return best.value
    return (best.op, *[self.extract(a) for a in best.args])

"""
emitter — real code from the contract IR (core slice) 

║  Path contracts (constraints -> result, straight-line branches) become   
║  real Python source. Emission is not trusted: the emitted function must  
║  pass verify_patch against the original or it is refused."""

from __future__ import annotations

from .ir import lower_condition, parse_expr, to_sym
from .sym import Op, Sym


def emit_sym(e) -> str:
    """sym tree -> Python expression text (the linear/boolean fragment)."""
    if isinstance(e, Sym):
        return e.name
    if isinstance(e, bool):
        return "True" if e else "False"
    if isinstance(e, int):
        return str(e)
    if isinstance(e, Op):
        op = e.op
        a = e.args
        if op == "not":
            return f"(not ({emit_sym(a[0])}))"
        if op in ("and", "or"):
            join = f" {op} "
            return "(" + join.join(f"({emit_sym(x)})" for x in a) + ")"
        if op == "=":
            return f"({emit_sym(a[0])} == {emit_sym(a[1])})"
        if len(a) == 1:                      # unary minus
            return f"(-{emit_sym(a[0])})"
        if op == "-" and a[0] == 0:
            return f"(-{emit_sym(a[1])})"    # 0 - n  ==>  -n
        if op in ("+", "-", "*", "<", "<=", ">", ">=", "==", "!="):
            return f"({emit_sym(a[0])} {op} {emit_sym(a[1])})"
    raise ValueError(f"emitter: cannot emit {e!r}")

