"""
extension

║  Rule packs as installable extensions (spec-kit shape): a manifest with   
║  id/version/effect/requires/provides, validated by contract.py, over      
║  a rules catalog.  Adding a capability = adding a manifest, not code."""

from __future__ import annotations

import json
import pathlib
from dataclasses import dataclass, field

from .contract import (manifest_contract, require, require_list,
                       validate_contract, check_semver)


@dataclass
class Extension:
    """One installed extension: manifest + its rule catalog."""
    manifest: dict
    rules: list[dict] = field(default_factory=list)
    path: pathlib.Path | None = None

    @property
    def id(self) -> str:
        """id(): see module docstring."""
        return self.manifest.get("bundle", {}).get("id", "?")

    @property
    def version(self) -> str:
        """version(): see module docstring."""
        return self.manifest.get("bundle", {}).get("version", "0.0.0")

    @property
    def commands(self) -> list[str]:
        """commands(): see module docstring."""
        return [c.get("name", "?")
                for c in self.manifest.get("provides", {}).get("commands", [])]

class ExtensionError(Exception):
    pass


def load_extension(path: str | pathlib.Path) -> Extension:
    """Load + validate an extension directory or single JSON file.

    Accepts either a manifest.json/catalog.json pair or a combined file with
    both 'manifest' and 'rules' keys."""
    p = pathlib.Path(path)
    raw = json.loads(p.read_text(encoding="utf-8"))
    if "manifest" in raw:    # combined file (our catalogs)
        manifest, rules = raw["manifest"], raw.get("rules", [])
    else:                    # manifest + rules.json side by side
        manifest = raw
        rp = p.with_name("rules.json")
        rules = json.loads(rp.read_text(encoding="utf-8"))["rules"] if rp.exists() else []
    errors = validate_contract(manifest, [manifest_contract])
    if errors:
        raise ExtensionError("; ".join(str(e) for e in errors))
    return Extension(manifest, rules, p)


def wrap_catalog(catalog_path: str | pathlib.Path, bundle_id: str,
                 version: str = "1.0.0",
                 effect: str = "read-write") -> dict:
    """Promote a bare rules catalog (secrules.json shape) into a full
    extension manifest — the open/closed upgrade path for existing packs."""
    cat = json.loads(pathlib.Path(catalog_path).read_text(encoding="utf-8"))
    rules = cat.get("rules", [])
    return {
        "manifest": {
            "bundle": {"id": bundle_id, "version": version, "effect": effect},
            "requires": {"engine_version": "1.0.0"},
            "provides": {"commands": [
                {"name": r["id"], "description": r.get("message", "")[:120]}
                for r in rules]},
        },
        "rules": rules,

    }


def installed_capabilities(extensions: list[Extension]) -> dict[str, list[str]]:
    """capability -> providing extension ids (the provides.commands index)."""
    caps: dict[str, list[str]] = {}
    for ext in extensions:
        for cmd in ext.commands:
            caps.setdefault(cmd, []).append(ext.id)
    return caps

"""facts.py -- datalog-style facts emission + tiny query evaluator.
Facts (calls, assigns, sinks, sources) over a parsed program; rules are
joins over facts -- fast, incremental, explainable (the CodeQL-lite seam)."""
from __future__ import annotations

import re


def collect_facts(source: str, lang: str = "python") -> dict:
    """{calls: [(f,g)], assigns: [(x, e)], sinks: [(line, name)]}."""
    import pipeline
    from pegrex.callgraph import build_call_graph
    from pegrex.peg import Node

    g = build_call_graph(source, lang)
    facts = {"calls": sorted(g.edges), "assigns": [], "sinks": []}
    from pegrex.languages import parse_source
    tree = None
    try:
        tree = parse_source(lang, source)
    except (ImportError, NotImplementedError, ValueError):
        tree = None
    if tree is not None:
        stack = [tree]
        while stack:
            n = stack.pop()
            if isinstance(n, Node):
                if n.tag == "assignment":
                    txt = source[n.pos:n.endpos].strip()
                    m = re.match(r"([A-Za-z_]\w*)\s*=", txt)
                    if m:
                        facts["assigns"].append((m.group(1),
                                                 txt.split("=", 1)[1].strip()[:40]))
                for c in n.children:
                    if isinstance(c, Node):
                        stack.append(c)
            elif isinstance(n, list):
                stack.extend(c for c in n if isinstance(c, Node))
    for ln, line in enumerate(source.splitlines(), 1):
        for name in ("system", "eval", "exec", "popen"):

            if re.search(rf"\b{name}\s*\(", line):
                facts["sinks"].append((ln, name))
    return facts


def query(facts: dict, body: list) -> list:
    """Micro-datalog: body literals (rel, a, b) with '_' wildcards, joined.
    Returns tuples from the FIRST literal satisfying all others."""
    rels = {"calls": facts["calls"], "assigns": facts["assigns"],
            "sinks": facts["sinks"]}
    first = body[0]
    out = []
    for tup in rels.get(first[0], []):
        if first[1] not in ("_", tup[0]):
            continue
        if len(tup) > 1 and first[2] not in ("_", tup[1]):
            continue
        ok = True
        for rel, a, b in body[1:]:
            if not any((a in ("_", x[0])) and
                       (len(x) < 2 or b in ("_", x[1]))
                       for x in rels.get(rel, [])):
                ok = False
                break
        if ok:
            out.append(tup)
    return out

