            for a in entry.get("atoms", []):
                try:
                    market_atoms.append(_normalize_atom_text(a))
                except LinearError:
                    continue    # non-linear book atom can entail nothing
            model = lb.learn(market_atoms)
            if es is not None and lb.entails(model, es):
                row["discharged_by"] = entry.get("name")
                row["verdict"] = "proved-by-market"
                break
        if row["verdict"] is None:
            row["verdict"] = "open"
            row["reason"] = ("no market entry's proven atoms entail this "
                             "obligation -- it stays open")
        results.append(row)
    return {"results": results,
            "discharged": sum(1 for r in results
                              if r["verdict"] == "proved-by-market"),
            "open": sum(1 for r in results if r["verdict"] == "open"),
            "unknown": sum(1 for r in results if r["verdict"] == "unknown")}


def quote(entry) -> dict:
    """Deterministic heuristic pricing: literal count x proof size, scaled by a fixed
    constant. The basis string says IN PLAIN WORDS that this is a
    documented heuristic, not a market price."""
    atoms = [str(a) for a in entry.get("atoms", [])]
    literals = len(atoms)

    def __new__(cls, kind: str, ty: str, value: object = None, args: tuple = ()):
        args = tuple(args)
        key = (cls, kind, ty, value, args)
        try:
            hash(key)
        except TypeError:
            return super().__new__(cls)
        with cls._lock:
            node = cls._nodes.get(key)
            if node is None:
                node = super().__new__(cls)
                cls._nodes[key] = node
            return node

    def __str__(self) -> str:
        """  str  (): see module docstring."""
        k = self.kind
        if k == "var":
            return str(self.value)
        if k == "const":
            return repr(self.value)
        if k == "not":
            return f"(not {self.args[0]})"
        if k == "bool":
            sep = f" {self.value} "
            return "(" + sep.join(str(a) for a in self.args) + ")"
        if k in ("bin", "cmp"):
            return "(" + f" {self.value} ".join(str(a) for a in self.args) + ")"
        if k == "call":
            return f"{self.value}(" + ", ".join(str(a) for a in self.args) + ")"
        if k == "field":
            return f"{self.args[0]}.{self.value}"
        return f"<{k}>"


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

_TOK = [

    ("num",   __import__("re").compile(r"\d+(?:\.\d+)?")),
    ("id",    __import__("re").compile(r"[A-Za-z_]\w*")),
    ("op",    __import__("re").compile(r"<=|>=|==|!=|=|&&|\|\||[+\-*/%<>&|]")),
    ("punct", __import__("re").compile(r"[(),.()]")),
    ("ws",    __import__("re").compile(r"\s+")),
]
_TY_CONST = {"true": ("bool", True), "false": ("bool", False)}


def tokenize(text: str):
    """tokenize(text): see module docstring."""
    import re
    toks, i, n = [], 0, len(text)
    while i < n:
        for kind, rx in _TOK:
            m = rx.match(text, i)
            if m:
                if kind != "ws":
                    toks.append((kind, m.group(0)))
                i = m.end()
                break
        else:
            raise CondError(f"ir: cannot tokenize at {text[i:]!r} (pos {i})")
    return toks


# ---------------------------------------------------------------------------
# Pratt parser
# ---------------------------------------------------------------------------

_CMP_OPS  = {"<": Lt, "<=": Le, ">": Gt, ">=": Ge, "==": Eq, "=": Eq,
           "!=": lambda a, b: Not(Eq(a, b))}
_BIN_TY   = {"+": "int", "-": "int", "*": "int", "/": "unknown", "%": "int"}
_PREC     = {"||": 1, "&&": 2, "==": 3, "!=": 3, "=": 3, "<": 4, "<=": 4, ">": 4, ">=": 4,
             "+": 5, "-": 5, "*": 6, "/": 6, "%": 6}
_RIGHT    = set()


def parse_expr(text: str) -> Expr:
    """Implement parse expr with the module's explicit API and failure semantics."""

toks = tokenize(text)
pos = [0]

def peek():
    """Implement peek with the module's explicit API and failure semantics."""
    return toks[pos[0]] if pos[0] < len(toks) else (None, None)

def next_():
    """Implement next with the module's explicit API and failure semantics."""
    if pos[0] >= len(toks):
        raise CondError("ir: unexpected end of condition")
    t = toks[pos[0]]
    pos[0] += 1
    return t

def expect(kind, val=None):
    """Implement expect with the module's explicit API and failure semantics."""
    k, v = next_()
    if k != kind or (val is not None and v != val):
        raise CondError(f"ir: expected {val or kind}, got {v!r}")
    return v

def primary():
    """Implement primary with the module's explicit API and failure semantics."""
    kind, val = next_()
    if kind == "id" and val == "not":
        return Expr("not", "bool", None, (expr(4),))
    if kind == "id" and val in ("and", "or"):
        raise CondError(f"ir: misplaced {val!r}")
    if kind == "num":
        return Expr("const", "int", Fraction(val) if "." in val else int(val))
    if kind == "id":
        if val in _TY_CONST:
            ty, lit = _TY_CONST[val]
            return Expr("const", ty, lit)
        e = Expr("var", "int", val)
        # call or field chain
        while True:
            k, v = peek()
            if (k, v) == ("punct", "("):

                next_()
                args = []
                if peek() != ("punct", ")"):
                    args.append(expr(0))
                    while peek() == ("punct", ","):
                        next_()
                        args.append(expr(0))
                expect("punct", ")")
                e = Expr("call", "unknown", val, tuple(args))
            elif (k, v) == ("punct", "."):
                next_()
                fk, fv = next_()
                if fk != "id":
                    raise CondError("ir: field name expected after '.'")
                e = Expr("field", "unknown", fv, (e,))
            else:
                break
        return e
    if (kind, val) == ("punct", "("):
        e = expr(0)
        expect("punct", ")")
        return e
    if (kind, val) == ("op", "-"):
        z = primary()
        if z.kind == "const" and z.ty == "int":
            return Expr("const", "int", -z.value)
        return Expr("bin", "int", "-", (Expr("const", "int", 0), z))
    if kind == "id" or (kind, val) == ("punct", ")"):
        raise CondError(f"ir: unexpected {val!r}")
    raise CondError(f"ir: unexpected token {val!r}")

def expr(min_prec):
    """Implement expr with the module's explicit API and failure semantics."""
    left = primary()
    while True:
        k, v = peek()
        if k == "id" and v in ("and", "or"):
            v = "&&" if v == "and" else "||"
            k = "op"
        if k != "op" or v not in _PREC or _PREC[v] < min_prec:

                break
            next_()
            rhs = expr(_PREC[v] + (0 if v in _RIGHT else 1))
            if v in _CMP_OPS:
                left = Expr("cmp", "bool", v, (left, rhs))
            elif v in ("&&", "||"):
                left = Expr("bool", "bool", v, (left, rhs))
            else:
                left = Expr("bin", _BIN_TY[v], v, (left, rhs))
        return left

    e = expr(0)
    if pos[0] != len(toks):
        raise CondError(f"ir: trailing tokens in {text!r}")
    return e


def parse_condition(text: str) -> Expr:
    """Parse a full condition. Result kind is cmp/bool/not; anything else is
    not a condition -> CondError."""
    e = parse_expr(text)
    if e.kind not in ("cmp", "bool", "not"):
        raise CondError(f"ir: {text!r} is not a condition")
    return e


# ---------------------------------------------------------------------------
# Lowering: IR -> sym.py formula trees
# ---------------------------------------------------------------------------

def to_sym(e: Expr):
    """IR -> sym tree. Calls/fields become opaque Sym atoms (typed unknown)."""
    if e.kind == "var":
        return V(str(e.value))
    if e.kind == "const":
        return const(e.value) if e.ty == "bool" else e.value
    if e.kind == "bin":
        from .sym import Op as _Op
        return _Op(str(e.value), tuple(to_sym(a) for a in e.args))
    if e.kind == "cmp":

        return _CMP_OPS[str(e.value)](to_sym(e.args[0]), to_sym(e.args[1]))
    if e.kind == "bool":
        comb = And if e.value == "&&" else Or
        return comb(*[to_sym(a) for a in e.args])
    if e.kind == "not":
        return Not(to_sym(e.args[0]))
    if e.kind == "call":
        return V(str(e.value) + "(" + ", ".join(str(to_sym(a)) for a in e.args) + ")")
    if e.kind == "field":
        return V(str(to_sym(e.args[0])) + "." + str(e.value))
    raise CondError(f"ir: no lowering for kind {e.kind}")


@lru_cache(maxsize=8192)
def _linearize_cached(e) -> tuple[tuple, Fraction] | None:
    """Cached immutable linear form: sorted coefficient items plus constant."""
    from .sym import Op, Sym
    if isinstance(e, Sym):
        name = e.name
        if name in ("true", "false") or "(" in name or "." in name:
            return None
        return (((name, Fraction(1)),), Fraction(0))
    if isinstance(e, (int, Fraction)) and not isinstance(e, bool):
        return ((), Fraction(e))
    if isinstance(e, Op):
        if e.op in ("+", "-"):
            left = _linearize_cached(e.args[0])
            right = _linearize_cached(e.args[1])
            if left is None or right is None:
                return None
            coeffs = dict(left[0])
            for key, value in right[0]:
                coeffs[key] = coeffs.get(key, Fraction(0)) + (
                    value if e.op == "+" else -value)
            constant = left[1] + (right[1] if e.op == "+" else -right[1])
            return (tuple(sorted(coeffs.items())), constant)
        if e.op == "*":
            left = _linearize_cached(e.args[0])
            right = _linearize_cached(e.args[1])
            if left is None or right is None:

                return None
            if not left[0]:
                return (tuple(sorted((key, left[1] * value)
                                     for key, value in right[0])), left[1] * right[1])
            if not right[0]:
                return (tuple(sorted((key, value * right[1])
                                     for key, value in left[0])), left[1] * right[1])
            return None
    return None


def linearize(e) -> tuple[dict, Fraction] | None:
    """Return a fresh legacy ``(dict, constant)`` over a memoized linear form."""
    result = _linearize_cached(e)
    return None if result is None else (dict(result[0]), result[1])


linearize.cache_info = _linearize_cached.cache_info
linearize.cache_clear = _linearize_cached.cache_clear


