def _distance(a, b):
    rows = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        following = [i]
        for j, cb in enumerate(b, 1): following.append(min(following[-1] + 1, rows[j] + 1, rows[j-1] + (ca != cb)))
        rows = following
    return rows[-1]


