def _legacy_params(contracts):
    free = set()
    for cs, res in contracts:
        for c in cs:
            free |= set(re.findall(r"[A-Za-z_]\w*", str(c)))
        free |= set(re.findall(r"[A-Za-z_]\w*", str(res)))
    return sorted(v for v in free
                  if v not in ("and", "or", "not", "true", "false", "result"))


