SCHEMA = "pegrex.reachability-sca.v1"


def _python_usage(root):
    root = Path(root); usages, functions, unknowns = {}, {}, []
    for path in sorted(root.rglob("*.py")):
        if any(part in {".git", "__pycache__", "venv", ".venv"} for part in path.parts): continue
        module = ".".join(path.relative_to(root).with_suffix("").parts)
        try: tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
        except (OSError, SyntaxError, UnicodeError) as error:
            unknowns.append(f"{path}: {error}"); continue
        imports = {}
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names: imports[alias.asname or alias.name.split(".")[0]] = alias.name
            elif isinstance(node, ast.ImportFrom) and node.module:
                for alias in node.names: imports[alias.asname or alias.name] = node.module + "." + alias.name
        def dotted(node):
            """Implement dotted with the module's explicit API and failure semantics."""
            parts = []
            while isinstance(node, ast.Attribute): parts.append(node.attr); node = node.value
            if isinstance(node, ast.Name): parts.append(node.id)
            return ".".join(reversed(parts))
        def visit(body, owner):
            """Implement visit with the module's explicit API and failure semantics."""
            calls = []
            for node in ast.walk(ast.Module(body=body, type_ignores=[])):
                if isinstance(node, ast.Call):
                    raw = dotted(node.func); full = imports.get(raw.split(".")[0], raw.split(".")[0]) + ("." + ".".join(raw.split(".")[1:]) if "." in raw else "")
                    calls.append((full, path, getattr(node, "lineno", 1)))
                    package = full.split(".")[0]
                    usages.setdefault(package, []).append({"symbol": full, "file": str(path),
                        "line": node.lineno, "function": owner, "reachable": owner == module + ".$module"})
            functions[owner] = calls
        visit(tree.body, module + ".$module")

        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                visit(node.body, module + "." + node.name)
            importsites = []
        for name, target in imports.items():
            usages.setdefault(target.split(".")[0], []).append({"symbol": target, "file": str(path),
                "line": 1, "function": module + ".$module", "reachable": True, "import": True})
    reachable = {owner for owner in functions if owner.endswith(".$module")}
    changed = True
    while changed:
        changed = False
        for owner in sorted(reachable):
            for symbol, _path, _line in functions.get(owner, []):
                for callee in functions:
                    if callee not in reachable and (callee == symbol or callee.endswith("." + symbol)):
                        reachable.add(callee); changed = True
    for sites in usages.values():
        for site in sites:
            site["reachable"] = site.get("function") in reachable
    return usages, unknowns


def scan_reachable(lockfile, source_root, *, vulnerable_calls=None, offline=False,
                   snapshot=None, cache_path=None) -> dict:
    """Add repository call evidence while retaining the underlying OSV UNKNOWNs."""
    base = scan(str(lockfile), offline=offline, snapshot=snapshot, cache_path=cache_path)
    usages, unknowns = _python_usage(Path(source_root))
    mapping = vulnerable_calls or {}
    findings = []
    for vulnerability in base["vulnerabilities"]:
        package = vulnerability["name"].replace("-", "_").split(".")[0]
        sites = usages.get(package, [])
        symbols = (mapping.get(vulnerability["id"]) or mapping.get(vulnerability["name"])
                   or vulnerability.get("affected_functions") or vulnerability.get("symbols"))
        matches = [] if not symbols else [site for site in sites if site.get("symbol") in symbols]
        reachable = [site for site in matches if site.get("reachable")]
        if reachable:
            status, reason = "reachable", "reachable static call to a declared vulnerable symbol"
        elif not symbols:
            status, reason = "unknown", "vulnerable symbol information unavailable; import alone is not vulnerable-call reachability"

    elif unknowns:
        status, reason = "unknown", "repository coverage incomplete"
    else:
        status, reason = "not-observed", "no reachable declared vulnerable call observed in scanned Python source; not a proof of absence"
    findings.append({**vulnerability, "installed": True, "reachability": status,
                     "reachability_reason": reason, "call_sites": matches,
                     "dependency_import_observed": bool(sites),
                     "evidence_strength": "static-call-graph" if reachable else "incomplete-or-negative-observation"})
return {"schema": SCHEMA, "schema_version": 1,
        "verdict": "unknown" if base["unknowns"] or unknowns or any(row["reachability"] == "unknown" for row in findings) else "ok",
        "inventory": base, "findings": findings,
        "unknowns": base["unknowns"] + [{"source": str(source_root), "reason": row} for row in unknowns],
        "scope": "installed inventory plus static Python call reachability; dynamic and external callers are not exhaustively modeled"}

def walk(n):
    """Implement walk with the module's explicit API and failure semantics."""
    if isinstance(n, Node):
        if n.tag == "call":
            txt = src[n.pos:n.endpos]
            if fn_name + "(" in txt:
                calls.append(n)
        for c in n.children:
            walk(c)
    elif isinstance(n, list):
        for c in n:
            walk(c)

def find_returns(n, acc):
    """Implement find returns with the module's explicit API and failure semantics."""
    if isinstance(n, Node):
        if n.tag == "return_statement":
            acc.append(n)
        for c in n.children:
            find_returns(c, acc)
    elif isinstance(n, list):
        for c in n:
            find_returns(c, acc)

    atoms = []
    for c in path_constraints:
        n = _norm_constraint(str(c))
        try:
            parse_atom(n)   # raises LinearError if opaque
            atoms.append(n)
        except Exception:
            pass            # opaque: dropped, safe direction
    model = lb.learn(atoms)
    out = {"requires": [], "ensures": []}
    for r in contracts["requires"]:
        try:
            rs = lower_condition(r)
            neg_probe = lb.learn(atoms + [cond_to_atom(_neg(rs))])
            out["requires"].append(
                {"contract": r, "status":
                 "violated" if neg_probe.feasible() else "respected"})
        except Exception:
            out["requires"].append({"contract": r, "status": "undischarged"})
    for e in contracts["ensures"]:
        sub = re.sub(r"\bresult\b", f"({result})", e)
        try:
            es = lower_condition(sub)
            es_neg = _neg(es)
            pos = lb.entails(model, es)
            neg = lb.entails(model, es_neg)
            out["ensures"].append({"contract": e, "substituted": sub,
                                   "status": "violated" if neg else
                                             "discharged" if pos else
                                             "undischarged"})
        except Exception:
            out["ensures"].append({"contract": e, "substituted": sub,
                                   "status": "undischarged"})
    return out


def _neg(sym_cond):
    from .sym import Not, Op
    if isinstance(sym_cond, Op) and sym_cond.op == "not" and len(sym_cond.args) == 1:
        return sym_cond.args[0]  # negation of a negation

    if isinstance(sym_cond, Op) and sym_cond.op in ("<", "<=", ">", ">=", "="):
        flip = {"<": ">=", "<=": ">", ">": "<=", ">=": "<", "=": "!="}[sym_cond.op]
        return Op(flip, sym_cond.args)
    return Not(sym_cond)


def discharge_source(src_path, contracts, lb=None) -> list:
    """All paths of a source file, each with its verdicts."""
    from . import api
    out = []
    for cs, res in api.contracts(src_path):
        out.append({"constraints": sorted(map(str, cs)), "result": str(res),
                    **discharge(cs, str(res), contracts, lb)})
    return out

def verify_package(manifest: dict, key: str) -> dict:
    """Independent re-verification of a certified manifest's signature."""
    if not isinstance(manifest, dict):
        return {"ok": False, "reason": "not a manifest"}
    body = {k: v for k, v in manifest.items() if k != "signature"}
    sig = manifest.get("signature")
    if not hmac_verify(body, key, sig):
        return {"ok": False, "reason": "signature mismatch (tampered or wrong key)"}
    return {"ok": True, "name": body.get("name"), "version": body.get("version")}


def load_registry(path) -> dict:
    """Implement load registry with the module's explicit API and failure semantics."""
    p = pathlib.Path(path)
    if not p.exists():
        return {}
    return json.loads(p.read_text(encoding="utf-8"))


def save_registry(path, registry: dict) -> None:
    """Implement save registry with the module's explicit API and failure semantics."""
    pathlib.Path(path).write_text(
        json.dumps(registry, indent=1, sort_keys=True) + "\n", encoding="utf-8")


def find_regressions(old_manifest: dict, new_manifest: dict) -> list:
    """Every proven property in old_manifest's files that is no longer
    proven in the corresponding new_manifest file -- a removed/renamed
    file counts as losing everything it once proved. Named per
    (file, property), not just a count: a regression report must say
    exactly what broke."""
    regressions = []
    old_certified = old_manifest.get("certified", {})
    new_certified = new_manifest.get("certified", {})
    for fname, old_info in sorted(old_certified.items()):
        new_info = new_certified.get(fname)
        old_proven = set(old_info.get("proven", []))
        new_proven = set(new_info.get("proven", [])) if new_info else set()

        for prop in sorted(old_proven - new_proven):
            regressions.append({"file": fname, "property": prop})
    return regressions


def publish(name: str, version: str, source_files: dict, key: str,
           registry_path) -> dict:
    """Certify the new version, then refuse if it regresses the
    previously-registered version's proven properties. The registry only
    advances to the new version on success -- a refused publish leaves
    the old, still-good version as the registered one."""
    new_manifest = certify_package(name, version, source_files, key)
    registry = load_registry(registry_path)
    old_manifest = registry.get(name)
    if old_manifest is not None:
        v = verify_package(old_manifest, key)
        if not v["ok"]:
            return {"status": "refused", "layer": "integrity",
                    "reason": f"registered manifest for {name!r} failed "
                              f"its own signature check: {v['reason']}"}
        regressions = find_regressions(old_manifest, new_manifest)
        if regressions:
            return {"status": "refused", "layer": "regression",
                    "regressions": regressions,
                    "old_version": old_manifest["version"],
                    "new_version": version}
    registry[name] = new_manifest
    save_registry(registry_path, registry)
    return {"status": "published", "name": name, "version": version,
            "proven_counts": {f: len(info["proven"])
                              for f, info in new_manifest["certified"].items()}}

"""Persistent fixed-finding regressions and rule-negative controls."""
from __future__ import annotations
import hashlib,json,os
from pathlib import Path
SCHEMA="pegrex.security-regression-memory.v1"

def _scan(source,rule):
    from .flow import analyze_source
    return any(row.get("id")==rule for row in analyze_source(source)["findings"])

def register_finding_fix(finding,vulnerable_source,fixed_source,test_path,memory_path) -> dict:
    """Refuse registration unless the rule fires before and stays absent after."""
    rule=finding.get("id")
    if not rule: return {"schema":SCHEMA,"status":"unknown","unknowns":["stable finding id required"]}
    if not _scan(vulnerable_source,rule):
        return {"schema":SCHEMA,"status":"unknown","unknowns":["rule-negative control does not reproduce the original finding"]}
    if _scan(fixed_source,rule):
        return {"schema":SCHEMA,"status":"refuted","unknowns":["fixed source still triggers the finding"]}
    test_path=Path(test_path);test_path.parent.mkdir(parents=True,exist_ok=True)
    identity=hashlib.sha256((rule+"\0"+vulnerable_source+"\0"+fixed_source).encode()).hexdigest()
    test=f"""# Generated PegRex security regression {identity}.
from pegrex.flow import analyze_source
RULE_ID = {rule!r}
VULNERABLE = {vulnerable_source!r}
FIXED = {fixed_source!r}
def findings(source):
    return analyze_source(source)["findings"]
def test_fixed_finding_{identity[:12]}():
    assert RULE_ID not in {{row["id"] for row in findings(FIXED)}}
def test_rule_negative_control_{identity[:12]}():
    assert RULE_ID in {{row["id"] for row in findings(VULNERABLE)}}
"""
    test_path.write_text(test, encoding="utf-8")
    memory_path=Path(memory_path);memory_path.parent.mkdir(parents=True,exist_ok=True)
    try: document=json.loads(memory_path.read_text(encoding="utf-8"))
    except (OSError,ValueError): document={"schema":SCHEMA,"schema_version":1,"entries":[]}
    row={"identity":identity,"finding":finding,"vulnerable_sha256":hashlib.sha256(vulnerable_source.encode()).hexdigest(),
         "fixed_sha256":hashlib.sha256(fixed_source.encode()).hexdigest(),"test_path":str(test_path),
         "test_sha256":hashlib.sha256(test.encode()).hexdigest(),"negative_control":"original vulnerable source must trigger rule"}
    if not any(row["identity"]==entry["identity"] for entry in document["entries"]): document["entries"].append(row)

    document["entries"].sort(key=lambda row:row["identity"])
    temporary=memory_path.with_suffix(memory_path.suffix+".tmp");temporary.write_text(json.dumps(document,sort_keys=True,indent=2)+"\n", encoding="utf-8");os.replace(temporary,memory_path)
    return {"schema":SCHEMA,"status":"registered","entry":row,"unknowns":[]}

def verify_regression_memory(memory_path) -> dict:
    """Implement verify regression memory with the module's explicit API and failure semantics."""
    try: document=json.loads(Path(memory_path).read_text(encoding="utf-8"))
    except (OSError,ValueError) as error:return {"schema":SCHEMA,"status":"unknown","unknowns":[str(error)]}
    unknowns=[]
    for row in document.get("entries",[]):
        try:
            if hashlib.sha256(Path(row["test_path"]).read_bytes()).hexdigest()!=row["test_sha256"]:unknowns.append("test artifact changed: "+row["identity"])
        except OSError as error:unknowns.append(str(error))
    return {"schema":SCHEMA,"status":"ok" if not unknowns else "unknown","entries":len(document.get("entries",[])),"unknowns":unknowns}

"""Proof-carrying repository release evidence with machine-checkable UNKNOWNs."""
from __future__ import annotations

import hashlib
import json
from collections import Counter
from pathlib import Path

from .buildprovenance import create_build_provenance, verify_build_provenance
from .repomemory import RepositoryMemory
from .sbom import generate_sbom
from .semantics import explain_patch

SCHEMA = "pegrex.proof-carrying-release.v1"


def _identity(value) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                    default=str).encode()).hexdigest()


def _unknown_summary(unknowns) -> dict:
    rows = sorted(set(str(row) for row in unknowns))
    categories = Counter(row.split(":", 1)[0] if ":" in row else "general" for row in rows)
    return {"schema": "pegrex.release-unknown-summary.v1", "complete": True,
            "count": len(rows), "by_category": dict(sorted(categories.items())),
            "entries": rows, "summary_sha256": _identity(rows)}


def _contract_release_diff(before, after, before_root, after_root) -> dict:
    rows, unknowns = [], []
    before_apis = before.apis if before else {}
    for key in sorted(set(before_apis) | set(after.apis)):
        old, new = before_apis.get(key), after.apis.get(key)
        if old == new:
            continue
        row = {"api": key, "change": "modified" if old and new else "removed" if old else "added",
               "before_identity": old and old.get("api_identity"),
               "after_identity": new and new.get("api_identity"), "verdict": "unknown"}
        if old and new and old["path"] == new["path"]:

            before_path, after_path = before_root / old["path"], after_root / new["path"]
            try:
                explanation = explain_patch(str(before_path), str(after_path))
                row.update(verdict=explanation["verdict"], evidence=explanation)
                unknowns.extend(f"semantic-diff:{key}:{reason}" for reason in explanation["unknowns"])
            except Exception as error:
                row["unknowns"] = [f"semantic diff failed: {type(error).__name__}: {error}"]
                unknowns.append(f"semantic-diff:{key}:unavailable")
        else:
            unknowns.append(f"semantic-diff:{key}:added or removed API is not equivalence evidence")
        rows.append(row)
    verdict = ("refuted" if any(row["verdict"] == "refuted" for row in rows) else
               "unknown" if unknowns or any(row["verdict"] == "unknown" for row in rows) else "proved")
    return {"schema": "pegrex.release-semantic-diff.v1", "verdict": verdict,
            "changes": rows, "unknowns": sorted(set(unknowns)),
            "before_memory_identity": before and before.memory_identity,
            "after_memory_identity": after.memory_identity}


def _sbom_unknowns(document) -> list[str]:
    if document is None:
        return ["sbom:no supported lockfile supplied"]
    if document.get("bomFormat") == "CycloneDX":
        return ["sbom:" + row["value"] for row in document.get("metadata", {}).get("properties", [])
                if row.get("name") == "pegrex:unknown"]
    comment = json.loads(document.get("documentComment", "{}"))
    return ["sbom:" + row for row in comment.get("unknowns", [])]


def create_proof_carrying_release(root, *, subjects, builder_id, command_argv, build_type,
                                  previous_root=None, lockfile=None, materials=None,
                                  internal_parameters=None) -> dict:
    """Collect independently checkable release sections; never hide missing evidence."""
    root = Path(root).resolve()
    previous = Path(previous_root).resolve() if previous_root is not None else None
    unknowns = []
    try:
        memory = RepositoryMemory(root)
        memory.refresh()
        contracts = []

        payload["verdict"] = "unknown" if unknowns else "proved"
        payload["scope"] = "release evidence and hash verification; unsigned provenance is not builder authentication"
        return payload
    except Exception as error:
        unknowns.append(f"release:evidence creation failed: {type(error).__name__}: {error}")
        return {"schema": SCHEMA, "schema_version": 1, "verdict": "unknown",
                "unknown_summary": _unknown_summary(unknowns)}


def verify_release_pack(pack, root, *, previous_root=None, lockfile=None,
                        subject_paths=None, material_paths=None) -> dict:
    """Recheck artifact identities and all available upstream evidence."""
    unknowns = []
    try:
        if pack.get("schema") != SCHEMA:
            raise ValueError("unsupported release evidence schema")
        identity_payload = {key: pack[key] for key in (
            "schema", "schema_version", "api_contracts", "sbom", "sbom_sha256",
            "build_attestation", "build_verification", "semantic_diff")}
        if _identity(identity_payload) != pack.get("release_identity"):
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                    "unknowns": ["release identity mismatch"]}
        memory = RepositoryMemory(Path(root).resolve())
        memory.refresh()
        if memory.memory_identity != pack["api_contracts"].get("memory_identity"):
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                    "unknowns": ["API contract memory identity mismatch"]}
        if pack.get("sbom") is None:
            unknowns.append("sbom:no supported lockfile supplied")
        elif lockfile is not None:
            regenerated = generate_sbom(lockfile)
            if _identity(regenerated) != pack.get("sbom_sha256"):
                return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                        "unknowns": ["SBOM identity mismatch"]}
        else:
            unknowns.append("sbom:upstream lockfile not supplied for independent regeneration")
        build = verify_build_provenance(pack["build_attestation"],
            subject_paths=subject_paths, material_paths=material_paths)
        if build["verdict"] == "refuted":
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",

                "unknowns": ["build subject or material hash mismatch"]}
    unknowns.extend("build:" + row for row in build["unknowns"])
    unknowns.append("build:unsigned attestation does not authenticate builder identity or hermeticity")
    if previous_root is not None:
        before = RepositoryMemory(Path(previous_root).resolve())
        before.refresh()
        semantic = _contract_release_diff(before, memory, Path(previous_root).resolve(), Path(root).resolve())
        if _identity(semantic) != _identity(pack["semantic_diff"]):
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                    "unknowns": ["semantic diff evidence mismatch"]}
    else:
        unknowns.append("previous-release:not independently reverified")
    unknowns.extend(pack.get("unknown_summary", {}).get("entries", []))
    summary = _unknown_summary(unknowns)
    return {"schema": SCHEMA, "verified": not unknowns, "verdict": "unknown" if unknowns else "proved",
            "release_identity": pack["release_identity"], "build_verification": build,
            "unknown_summary": summary}
except Exception as error:
    return {"schema": SCHEMA, "verified": False, "verdict": "unknown",
            "unknowns": [f"release verification failed: {type(error).__name__}: {error}"]}

target = Path(target).resolve()
original = target.read_text(encoding="utf-8")
trail = []
try:
    baseline = analyzer(str(target))
except Exception as error:
    return {"schema": SCHEMA, "status": "unknown", "applied": False,
            "unknowns": [f"baseline-analysis-failed:{error}"], "trail": []}
baseline_policy = evaluate_security_policy(baseline, profile)
if not baseline_policy["allowed"]:
    return {"schema": SCHEMA, "status": "policy-refused", "applied": False,
            "baseline": baseline, "policy": baseline_policy, "trail": []}
rule_id = finding.get("id")
if not rule_id:
    return {"schema": SCHEMA, "status": "unknown", "applied": False,
            "unknowns": ["finding-without-stable-id"], "trail": []}
baseline_counts = _identities(baseline)
matching = sum(count for (identifier, _), count in baseline_counts.items() if identifier == rule_id)
if not matching:
    return {"schema": SCHEMA, "status": "finding-not-present", "applied": False,
            "baseline": baseline, "trail": []}
feedback = None
for round_number in range(1, max_rounds + 1):
    current = target.read_text(encoding="utf-8")
    try:
        proposal = generator(current, finding, feedback)
    except Exception as error:
        trail.append({"round": round_number, "status": "generator-error", "error": str(error)})
        feedback = trail[-1]
        continue
    if proposal is None:
        trail.append({"round": round_number, "status": "no-candidate"})
        break
    try:
        if not isinstance(proposal, str):
            raise TypeError("repair candidate must be complete source text")
        ast.parse(proposal)
    except (SyntaxError, TypeError, ValueError) as error:
        trail.append({"round": round_number, "status": "invalid-candidate", "error": str(error)})
        feedback = trail[-1]

    continue

def recheck(staged):
    """Implement recheck with the module's explicit API and failure semantics."""
    report = analyzer(staged)
    policy = evaluate_security_policy(report, profile)
    counts = _identities(report)
    remaining = sum(count for (identifier, _), count in counts.items() if identifier == rule_id)
    increased = [{"id": identifier, "function": function,
                  "before": baseline_counts[(identifier, function)], "after": count}
                 for (identifier, function), count in sorted(counts.items(), key=str)
                 if count > baseline_counts[(identifier, function)]]
    resolved = remaining < matching
    allowed = resolved and not increased and policy["allowed"]
    additional = None
    if candidate_validator is not None:
        try:
            additional = candidate_validator(staged)
            if not isinstance(additional, dict) or "allowed" not in additional:
                additional = {"allowed": False,
                              "unknowns": ["invalid-additional-candidate-validation"]}
        except Exception as error:
            additional = {"allowed": False,
                          "unknowns": [f"additional-candidate-validation-error:{error}"]}
        allowed = allowed and additional["allowed"] is True
    return {"allowed": allowed, "finding_resolved": resolved,
            "remaining_matching_findings": remaining,
            "new_or_increased_findings": increased,
            "policy": policy, "before": baseline, "after": report,
            "additional_validation": additional}

gate = apply_patch_gated(target, proposal, profile=profile,
    require_equivalent=False, invariants=invariants, test_command=test_command,
    project_root=project_root, audit_dir=audit_dir, timeout_ms=timeout_ms,
    actor="repair-and-recheck", candidate_check=recheck)
row = {"round": round_number, "status": "accepted" if gate["applied"] else "rejected",
       "gate": gate, "candidate_sha256": gate.get("after_sha256")}
trail.append(row)
if gate["applied"]:
    return {"schema": SCHEMA, "status": "repaired", "applied": True,

                    "rounds": round_number, "trail": trail, "patch": proposal,
                    "before": baseline, "after": gate["candidate_check"]["after"],
                    "audit_attempt_id": gate["audit_attempt_id"], "unknowns": []}
        feedback = {"gate": gate, "candidate_check": gate.get("candidate_check")}
    return {"schema": SCHEMA, "status": "unresolved", "applied": False,
            "rounds": len(trail), "trail": trail,
            "unchanged": target.read_text(encoding="utf-8") == original,
            "unknowns": ["no-repair-satisfied-recheck-and-policy"]}


def sandboxed_differential(before_path, after_path, *, argv, files=None,
                           target_name=None, timeout_ms=5000, memory_mb=256) -> dict:
    """Compare bounded observations of two source versions in separate sandboxes.

    Matching output is a passed differential test, never an equivalence proof.
    The caller supplies an argv-only harness and any auxiliary declared files.
    """
    schema = "pegrex.sandboxed-differential.v1"
    if isinstance(argv, str) or not argv or any(not isinstance(row, str) for row in argv):
        return {"schema": schema, "status": "unknown", "verdict": "unknown",
                "allowed": False, "unknowns": ["differential harness requires argv"]}
    target_name = target_name or Path(before_path).name
    relative = Path(target_name)
    if relative.is_absolute() or ".." in relative.parts or not relative.parts:
        return {"schema": schema, "status": "unknown", "verdict": "unknown",
                "allowed": False, "unknowns": ["unsafe differential target path"]}
    declared = dict(files or {})
    if target_name in declared:
        return {"schema": schema, "status": "unknown", "verdict": "unknown",
                "allowed": False, "unknowns": ["differential target collides with declared files"]}
    try:
        before_source = Path(before_path).read_bytes()
        after_source = Path(after_path).read_bytes()
    except OSError as error:
        return {"schema": schema, "status": "unknown", "verdict": "unknown",
                "allowed": False, "unknowns": [str(error)]}
    before_files = declared | {target_name: before_source}
    after_files = declared | {target_name: after_source}
    before = run_poc(argv, files=before_files, timeout_ms=timeout_ms,
                     memory_mb=memory_mb)

    if not before.get("executed"):
        return {"schema": schema, "status": "unknown", "verdict": "unknown",
                "allowed": False, "before": before, "after": None,
                "unknowns": before.get("unknowns") or ["before execution unavailable"]}
    after = run_poc(argv, files=after_files, timeout_ms=timeout_ms,
                    memory_mb=memory_mb)
    if not after.get("executed"):
        return {"schema": schema, "status": "unknown", "verdict": "unknown",
                "allowed": False, "before": before, "after": after,
                "unknowns": after.get("unknowns") or ["after execution unavailable"]}
    observations_match = (before.get("returncode") == after.get("returncode") and
                          before.get("evidence", "") == after.get("evidence", "") and
                          before.get("status") != "unknown" and after.get("status") != "unknown")
    if not observations_match:
        return {"schema": schema, "status": "different", "verdict": "refuted",
                "allowed": False, "observations_match": False,
                "before": before, "after": after,
                "unknowns": [], "counterexample": {
                    "confirmed": True, "kind": "sandboxed-differential",
                    "before_returncode": before.get("returncode"),
                    "after_returncode": after.get("returncode")}}
    return {"schema": schema, "status": "passed", "verdict": "unknown",
            "allowed": True, "observations_match": True,
            "before": before, "after": after,
            "unknowns": ["bounded differential observations do not prove semantic equivalence"]}


def _independent_validation(checker, before, after) -> dict:
    try:
        evidence = checker(str(before), str(after))
    except Exception as error:
        return {"allowed": False, "verdict": "unknown", "evidence": None,
                "unknowns": [f"independent-validation-error:{error}"]}
    if isinstance(evidence, bool):
        verdict = "proved" if evidence else "unknown"
        allowed = evidence
        unknowns = [] if evidence else ["independent checker did not prove validity"]
    elif isinstance(evidence, dict):
        verdict = evidence.get("verdict", "unknown")
        if verdict not in {"proved", "refuted", "unknown"}:

            verdict = "unknown"
        allowed = verdict == "proved" and evidence.get("allowed", True) is True
        unknowns = list(evidence.get("unknowns") or [])
        if not allowed and not unknowns:
            unknowns = ["independent checker did not prove validity"]
    else:
        verdict, allowed = "unknown", False
        unknowns = ["invalid independent checker result"]
    return {"allowed": allowed, "verdict": verdict, "evidence": evidence,
            "unknowns": unknowns}


