from pathlib import Path, PurePosixPath

from .kernel import check_certificate
from .regressionmemory import register_finding_fix

SCHEMA = "pegrex.security-research-capsule.v1"


def _sha(data):
    return hashlib.sha256(data).hexdigest()


def _json_bytes(value):
    return (json.dumps(value, sort_keys=True, indent=2, default=str) + "\n").encode()


def _identity(value):
    return _sha(json.dumps(value, sort_keys=True, separators=(",", ":"), default=str).encode())


def create_research_capsule(output, *, finding, minimized_source, fixed_source,
                            exploit_preconditions, sandbox_argv, regression_test_path=None,
                            minimization_evidence=None, proof_or_witness=None) -> dict:
    """Package finding-to-fix evidence without executing the exploit recipe."""
    unknowns = []
    try:
        if isinstance(sandbox_argv, str) or not sandbox_argv or any(not isinstance(row, str) for row in sandbox_argv):
            raise ValueError("sandbox recipe requires structured argv")
        output = Path(output)
        output.parent.mkdir(parents=True, exist_ok=True)
        test_name = PurePosixPath(regression_test_path or "regression_test.py").name
        memory_name = "regression_memory.json"
        registration = register_finding_fix(finding, minimized_source, fixed_source,

                                    output.parent / (output.stem + "." + test_name),
                                    output.parent / (output.stem + "." + memory_name))
if registration["status"] != "registered":
    return {"schema": SCHEMA, "status": "unknown", "verdict": "unknown",
            "unknowns": registration["unknowns"] + ["capsule not created"]}
test_path = Path(registration["entry"]["test_path"])
generated_memory_path = output.parent / (output.stem + "." + memory_name)
memory_document = json.loads(generated_memory_path.read_text(encoding="utf-8"))
for entry in memory_document["entries"]:
    entry["test_path"] = test_name
test_bytes = test_path.read_bytes()
memory_bytes = _json_bytes(memory_document)
test_path.unlink(); generated_memory_path.unlink()
if not minimization_evidence or not minimization_evidence.get("confirmed"):
    unknowns.append("source minimization is declared but not independently confirmed")
proof_status = "unknown"
if proof_or_witness:
    certificate = proof_or_witness.get("certificate")
    if certificate:
        checked = check_certificate(certificate)
        proof_status = "verified" if checked.get("verdict") == "proved" else "unknown"
        if proof_status != "verified":
            unknowns.append("supplied certificate did not pass the minimal kernel")
    elif (proof_or_witness.get("counterexample") or {}).get("confirmed"):
        proof_status = "confirmed-witness"
    else:
        unknowns.append("proof/witness evidence is unconfirmed")
else:
    unknowns.append("proof or confirmed witness not supplied")
recipe = {"schema": "pegrex.capsule-sandbox-recipe.v1", "argv": list(sandbox_argv),
          "files": {"vulnerable.min": "vulnerable.min", "regression_test.py": test_name},
          "timeout_ms": 5000, "memory_mb": 256, "network": "disabled",
          "credentials": "none", "execution": "not-requested",
          "backend": "ephemeral bubblewrap+prlimit required"}
files = {"finding.json": _json_bytes(finding), "vulnerable.min": minimized_source.encode(),
         "fixed.py": fixed_source.encode(),
         "exploit-preconditions.json": _json_bytes(exploit_preconditions),
         "sandbox-recipe.json": _json_bytes(recipe), test_name: test_bytes,
         memory_name: memory_bytes,
         "proof-or-witness.json": _json_bytes(proof_or_witness),

                 "minimization-evidence.json": _json_bytes(minimization_evidence)}
        entries = [{"path": name, "sha256": _sha(data), "bytes": len(data)}
                   for name, data in sorted(files.items())]
        manifest_payload = {"schema": SCHEMA, "schema_version": 1,
                            "finding_id": finding.get("id"), "artifacts": entries,
                            "sandbox_recipe_sha256": _sha(files["sandbox-recipe.json"]),
                            "proof_status": proof_status,
                            "source_minimized": bool(minimization_evidence and minimization_evidence.get("confirmed"))}
        manifest_payload["capsule_identity"] = _identity(manifest_payload)
        manifest = dict(manifest_payload, unknowns=sorted(set(unknowns)),
                        scope="content-addressed research evidence; recipe inclusion is not execution or exploit confirmation")
        manifest_bytes = _json_bytes(manifest)
        with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
            for name, data in sorted(files.items()):
                info = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
                info.compress_type = zipfile.ZIP_DEFLATED; info.external_attr = 0o600 << 16
                archive.writestr(info, data)
            info = zipfile.ZipInfo("manifest.json", (1980, 1, 1, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED; info.external_attr = 0o600 << 16
            archive.writestr(info, manifest_bytes)
        return {"schema": SCHEMA, "status": "created", "verdict": "unknown" if unknowns else "proved",
                "path": str(output), "capsule_identity": manifest["capsule_identity"],
                "artifact_sha256": _sha(output.read_bytes()), "unknowns": manifest["unknowns"]}
    except Exception as error:
        return {"schema": SCHEMA, "status": "unknown", "verdict": "unknown",
                "unknowns": [f"capsule creation failed: {type(error).__name__}: {error}"]}


def verify_research_capsule(path) -> dict:
    """Verify containment, manifest identity, every artifact hash, and negative control."""
    unknowns = []
    try:
        with zipfile.ZipFile(path) as archive:
            names = archive.namelist()
            if len(names) != len(set(names)) or any(PurePosixPath(name).is_absolute() or ".." in PurePosixPath(name).parts
                                                    for name in names):
                raise ValueError("unsafe or duplicate capsule path")
            manifest = json.loads(archive.read("manifest.json"))
            payload = {key: manifest[key] for key in ("schema", "schema_version", "finding_id", "artifacts",
                       "sandbox_recipe_sha256", "proof_status", "source_minimized")}

        if payload["schema"] != SCHEMA or _identity(payload) != manifest.get("capsule_identity"):
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted", "unknowns": ["capsule identity mismatch"]}
        for row in manifest["artifacts"]:
            data = archive.read(row["path"])
            if _sha(data) != row["sha256"] or len(data) != row["bytes"]:
                return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                        "unknowns": [f"artifact hash mismatch: {row['path']}"]}
        finding = json.loads(archive.read("finding.json"))
        vulnerable = archive.read("vulnerable.min").decode()
        fixed = archive.read("fixed.py").decode()
        from .flow import analyze_source
        if finding["id"] not in {row["id"] for row in analyze_source(vulnerable)["findings"]}:
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                    "unknowns": ["original finding negative control no longer reproduces"]}
        if finding["id"] in {row["id"] for row in analyze_source(fixed)["findings"]}:
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                    "unknowns": ["fixed source still triggers original finding"]}
        recipe = json.loads(archive.read("sandbox-recipe.json"))
        if recipe.get("network") != "disabled" or recipe.get("credentials") != "none":
            return {"schema": SCHEMA, "verified": False, "verdict": "refuted",
                    "unknowns": ["unsafe sandbox recipe"]}
        unknowns.extend(manifest.get("unknowns") or [])
        unknowns.append("sandbox recipe was not executed by capsule verification")
        return {"schema": SCHEMA, "verified": not unknowns, "verdict": "unknown" if unknowns else "proved",
                "capsule_identity": manifest["capsule_identity"],
                "artifacts_verified": len(manifest["artifacts"]), "unknowns": sorted(set(unknowns))}
except Exception as error:
    return {"schema": SCHEMA, "verified": False, "verdict": "unknown",
            "unknowns": [f"capsule verification failed: {type(error).__name__}: {error}"]}

"""Conservative termination, allocation-site, and asymptotic bounds."""
from __future__ import annotations
import ast
SCHEMA = "pegrex.resource-bounds.v1"


def _range(node):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == "range" and len(node.args) == 1:
        if isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, int):
            return max(0, node.args[0].value), str(node.args[0].value)
        if isinstance(node.args[0], ast.Name): return None, node.args[0].id
    return None, None


def _block(statements, function, depth=0):
    allocations, exponent, unknowns = 0, 0, []
    termination = True
    allocation_expression = "0"
    def add_alloc(expr):
        """Implement add alloc with the module's explicit API and failure semantics."""
        nonlocal allocation_expression
        allocation_expression = allocation_expression + "+" + expr
    for statement in statements:
        for node in ast.walk(statement):
            if isinstance(node, (ast.List, ast.Dict, ast.Set, ast.ListComp, ast.SetComp, ast.DictComp)):
                allocations += 1; add_alloc("1")
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id == function:
                termination = False; unknowns.append("recursion outside termination fragment")
        if isinstance(statement, (ast.For, ast.While)):
            body_alloc, body_exp, body_term, body_unknown, body_expr = _block(statement.body, function, depth + 1)
            unknowns.extend(body_unknown); termination = termination and body_term
            if isinstance(statement, ast.For):
                count, label = _range(statement.iter)
                if label is None:
                    termination = False; exponent = None; unknowns.append("non-range loop bound unknown")
                else:
                    exponent = None if body_exp is None else body_exp + 1
                    if count is not None:
                        allocations += count * body_alloc; add_alloc(f"{count}*({body_expr})")
                    elif body_alloc:

                        allocations = None; add_alloc(f"{label}*({body_expr})")
            else:
                variant = False
                if isinstance(statement.test, ast.Compare) and len(statement.test.ops) == 1                         and isinstance(statement.test.left, ast.Name)                         and isinstance(statement.test.ops[0], (ast.Gt, ast.GtE)):
                    name = statement.test.left.id
                    variant = any(isinstance(row, ast.AugAssign) and isinstance(row.target, ast.Name)
                                  and row.target.id == name and isinstance(row.op, ast.Sub)
                                  and isinstance(row.value, ast.Constant) and row.value.value > 0
                                  for row in statement.body)
                if variant:
                    exponent = None if body_exp is None else body_exp + 1
                    if body_alloc: allocations = None; add_alloc(f"iterations*({body_expr})")
                else:
                    termination = False; exponent = None
                    if body_alloc: allocations = None
                    unknowns.append("while loop has no proved decreasing variant")
        elif isinstance(statement, ast.Break):
            unknowns.append("break outside structured resource fragment")
    return allocations, exponent, termination, unknowns, allocation_expression


def analyze_resource_bounds(source, *, function=None) -> dict:
    """Allocation means allocation sites, not byte-exact memory consumption."""
    try: tree = ast.parse(source)
    except SyntaxError as error:
        return {"schema": SCHEMA, "schema_version": 1, "verdict": "unknown", "functions": [],
                "unknowns": [f"parse error: {error}"]}
    rows = []
    for node in tree.body:
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) or (function and node.name != function): continue
        if isinstance(node, ast.AsyncFunctionDef):
            rows.append({"function": node.name, "verdict": "unknown", "unknowns": ["async resource fragment unsupported"]}); continue
        allocations, exponent, termination, unknowns, expression = _block(node.body, node.name)
        verdict = "proved" if termination and exponent is not None and allocations is not None and not unknowns else "unknown"
        rows.append({"function": node.name, "verdict": verdict,
                     "termination": "proved" if termination else "unknown",
                     "allocation_sites": allocations, "allocation_expression": expression,
                     "worst_case_complexity": "O(1)" if exponent == 0 else f"O(n^{exponent})" if exponent and exponent > 1 else "O(n)" if exponent == 1 else None,
                     "fragment": "structured range loops and simple decreasing integer while variants",
                     "unknowns": sorted(set(unknowns))})

unknowns = [f"{row['function']}: resource bound incomplete" for row in rows if row["verdict"] == "unknown"]
return {"schema": SCHEMA, "schema_version": 1,
        "verdict": "unknown" if unknowns or not rows else "proved",
        "functions": rows, "unknowns": unknowns}

def _renderer(lang: str, src: str):
    spec = get_language(lang)
    if spec.outcome_renderer == "c":
        return lambda st: render_c(st, src)
    def _render(st, _s=src, _mode=spec.outcome_renderer):
        t = st.children[0] if st.children and \
            isinstance(st.children[0], str) else _s[st.pos:st.endpos]
        return t.replace("return", "", 1).strip() if _mode == "strip-return" else t.strip()
    return _render


def _build_variant(variant, base_dir, unroll):
    """pipeline.run_spec's per-variant lowering, verbatim.  Returns
    {"language", "constraints", "contracts", "whole": None|list, "source"}
    or raises _VariantRefused with a loud reason."""
    import pipeline
    from .languages import normalize_language, get_language
    requested = variant.get("language")
    lang = normalize_language(requested)
    if lang is None:
        raise _VariantRefused(f"unknown language {requested!r} — no frontend")
    language_spec = get_language(lang)
    if "contracts" not in language_spec.capabilities:
        raise _VariantRefused(f"contracts unsupported for {lang!r}")
    if not language_spec.frontend_factory:
        raise _VariantRefused(
            f"{lang!r} supports native contract extraction but has no CFG frontend for Rosetta path comparison")
    src_path = pathlib.Path(variant["source"])
    if not src_path.is_absolute():
        src_path = base_dir / src_path
    src = src_path.read_text(encoding="utf-8")
    parse, tagspec, make_cond = pipeline.frontend_for(lang)
    try:
        body = parse(src)   # PREPROCESS
    except Exception as e:
        raise _VariantRefused(f"[{lang}] parse failure in {src_path.name}: "
                              f"{type(e).__name__}: {e}")
    cfg = CFGBuilder(tagspec).build(body)   # CFG

    cond = make_cond(src)
    constraints = pipeline.path_constraints(cfg, cond, unroll)
    render = _renderer(lang, src)
    contracts = path_summaries(cfg, cond, render, unroll)
    whole = None
    if "entry" in variant:  # multi-function variant
        if lang not in pipeline.FUNCTIONS:
            raise _VariantRefused(
                f"[{lang}] multi-function variant (entry="
                f"{variant['entry']!r}) unsupported — no FUNCTIONS entry "
                f"for {lang!r}")
        fn_bodies = pipeline.FUNCTIONS[lang](src)
        fn_contracts = {nm: path_summaries(CFGBuilder(tagspec).build(b),
                                           cond, render, unroll)
                        for nm, b in fn_bodies.items()}
        pnames = variant.get("params", {})
        entry = variant["entry"]
        callees = {nm: c for nm, c in fn_contracts.items() if nm != entry}
        whole = expand_calls(fn_contracts[entry], callees, pnames)
    return {"language": lang, "constraints": constraints,
            "contracts": contracts, "whole": whole, "source": str(src_path)}


class _VariantRefused(ValueError):
    pass


def _quote_path(p) -> str:
    return "[" + ", ".join(sorted(str(c) for c in p)) + "]"


def _quote_contract(t) -> str:
    cons, res = t
    return f"{_quote_path(cons)} -> {res!r}"


def _first_diff(a, b):
    """Index of first differing element; None if equal prefix and same len."""
    for i, (x, y) in enumerate(zip(a, b)):
        if x != y:

            return i
    if len(a) != len(b):
        return min(len(a), len(b))
    return None


def _compare_pair(va, vb):
    """-> (verdict, detail).  Equivalent iff raw constraints and contracts
    are equal (whole-program contracts too when both sides have them —
    mirroring run_spec's POSTPROCESS)."""
    detail = {}
    ci = _first_diff(va["constraints"], vb["constraints"])
    if ci is not None:
        qa = _quote_path(va["constraints"][ci]) if ci < len(va["constraints"]) \
            else "<no such path>"
        qb = _quote_path(vb["constraints"][ci]) if ci < len(vb["constraints"]) \
            else "<no such path>"
        detail["constraints"] = {"a": qa, "b": qb, "first_diff_index": ci}
    ti = _first_diff(va["contracts"], vb["contracts"])
    if ti is not None:
        qa = _quote_contract(va["contracts"][ti]) if ti < len(va["contracts"]) \
            else "<no such contract>"
        qb = _quote_contract(vb["contracts"][ti]) if ti < len(vb["contracts"]) \
            else "<no such contract>"
        detail["contracts"] = {"a": qa, "b": qb, "first_diff_index": ti}
    if va["whole"] is not None and vb["whole"] is not None:
        wi = _first_diff(va["whole"], vb["whole"])
        if wi is not None:
            qa = _quote_contract(va["whole"][wi]) if wi < len(va["whole"]) \
                else "<no such whole-contract>"
            qb = _quote_contract(vb["whole"][wi]) if wi < len(vb["whole"]) \
                else "<no such whole-contract>"
            detail["whole"] = {"a": qa, "b": qb, "first_diff_index": wi}
    return ("equivalent", None) if not detail else ("counterexample", detail)


def equivalence(spec) -> dict:
    """N-way cross-language equivalence over path contracts.

    spec: {"name": str, "variants": [{"language", "source", "entry"?,

                "unknowns": ["old and new runtime invokers are required for round-trip proof"]}
    by_operation = {operation: [] for operation in operations}
    for case in cases:
        if case.get("operation") in by_operation:
            by_operation[case["operation"]].append(case)
    rows, unknowns = [], []
    for operation in operations:
        if not by_operation[operation]:
            unknowns.append(f"no runtime round-trip case for {operation}")
    for index, case in enumerate(cases):
        operation = case.get("operation")
        if operation not in by_operation:
            unknowns.append(f"runtime case {index} names an unknown operation")
            continue
        params = case.get("params") or {}
        try:
            before = old_invoker(operation, params)
            after = new_invoker(operation, params)
            match = json.dumps(before, sort_keys=True, separators=(",", ":")) == json.dumps(
                after, sort_keys=True, separators=(",", ":"))
            rows.append({"operation": operation, "params": params,
                         "match": match, "before": before, "after": after,
                         "verdict": "proved" if match else "refuted"})
        except Exception as error:
            rows.append({"operation": operation, "params": params,
                         "verdict": "unknown", "error": str(error)})
            unknowns.append(f"runtime case {index} failed: {error}")
    verdict = ("refuted" if any(row["verdict"] == "refuted" for row in rows) else
               "unknown" if unknowns or any(row["verdict"] == "unknown" for row in rows) else "proved")
    return {"verdict": verdict, "cases": rows, "unknowns": unknowns}


def check_round_trip(spec, *, old_server=None, new_server=None,
                     old_client=None, new_client=None, old_invoker=None,
                     new_invoker=None, cases=()) -> dict:
    """Check both API generations and execute explicit old/new runtime cases.

    Generated stubs are always returned for tooling. Static agreement alone is
    not a round-trip proof: every operation needs a matching runtime case.
    """

try:
    stubs = generate_api_stubs(spec)
    ast.parse(stubs["python_server"] or "\n")
    sources = {
        "old_server": old_server if old_server is not None else stubs["python_server"],
        "new_server": new_server if new_server is not None else stubs["python_server"],
        "old_client": old_client if old_client is not None else stubs["go_client"],
        "new_client": new_client if new_client is not None else stubs["go_client"],
    }
    static = {}
    for name, source in sources.items():
        checker = check_python_server if name.endswith("server") else check_go_client
        static[name] = checker(source, spec)
    runtime = _runtime(old_invoker, new_invoker, stubs["operations"], cases)
    drift = [{"generation": side, **row} for side, rows in static.items() for row in rows]
    verdict = ("refuted" if drift or runtime["verdict"] == "refuted" else
               "unknown" if runtime["verdict"] == "unknown" else "proved")
    return {"schema": SCHEMA, "schema_version": 1, "verdict": verdict,
            "compatible": verdict == "proved", "static_drift": drift,
            "runtime": runtime, "generated_stubs": stubs,
            "unknowns": list(runtime["unknowns"]),
            "scope": "declared OpenAPI operations and supplied runtime cases"}
except Exception as error:
    return {"schema": SCHEMA, "schema_version": 1, "verdict": "unknown",
            "compatible": False, "unknowns": [f"round-trip check failed: {type(error).__name__}: {error}"]}

"""Canonical converted-rule deduplication, provenance, and coverage reporting."""
from __future__ import annotations

import hashlib
import json
import pathlib
from dataclasses import dataclass, field


@dataclass(frozen=True)
class RuleOrigin:
    pack: str
    upstream: str
    version: str
    index: int

    def to_dict(self) -> dict:
        """Implement to dict with the module's explicit API and failure semantics."""
        return {"pack": self.pack, "upstream": self.upstream,
                "version": self.version, "index": self.index}


@dataclass(frozen=True)
class RuleRecord:
    rule: dict
    origin: RuleOrigin
    semantics: str


@dataclass
class RulePack:
    records: list[RuleRecord] = field(default_factory=list)
    disabled: list[RuleRecord] = field(default_factory=list)
    duplicates: list[dict] = field(default_factory=list)
    packs: list[dict] = field(default_factory=list)

    @property
    def rules(self) -> list[dict]:
        """Implement rules with the module's explicit API and failure semantics."""
        return [record.rule for record in self.records]

    def catalog_version(self) -> str:
        """Exact, content-defined version of this executable catalog snapshot."""
        identity = {
            "packs": self.packs,
            "active": [[record.rule["id"], record.semantics]
                       for record in self.records],
            "disabled": [[record.rule["id"], record.semantics]
                         for record in self.disabled],
        }
        encoded = json.dumps(identity, sort_keys=True, separators=(",", ":"),
                             ensure_ascii=False).encode("utf-8")
        return "sha256:" + hashlib.sha256(encoded).hexdigest()

    def coverage(self, language: str | None = None, *,
                 rule_languages=frozenset()) -> dict:
        """Implement coverage with the module's explicit API and failure semantics."""
        applicable, inapplicable = [], []
        for record in self.records:
            langs = set(record.rule.get("langs", ()))
            applies = (language is None or not langs or "regex" in langs
                       or bool(langs & set(rule_languages)))
            (applicable if applies else inapplicable).append(record)
        return {
            "catalog_version": self.catalog_version(),
            "active": len(applicable),
            "disabled": len(self.disabled),
            "duplicates_removed": len(self.duplicates),
            "inapplicable": len(inapplicable),
            "inapplicable_rules": [record.rule["id"] for record in inapplicable],
            "disabled_rules": [record.rule["id"] for record in self.disabled],
            "provenance": list(self.packs),
        }


