def contracts_of(path: str):
    """[(frozenset(constraints), canonical-result)] via the engine frontend.
    Constraints are canonicalized through the IR: 'n > 0' and
    'not (n <= 0)' are the same path -- string-level diffs must not fake
    behavioral differences."""
    from .refine import _norm_constraint
    return [ (frozenset(_int_canon(_norm_constraint(str(c))) for c in cs),
              _canon_result(res))
             for cs, res in api.contracts(path) ]


def semantic_diff(path_a: str, path_b: str) -> dict:
    "Behavioral difference as changed path contracts."
    ca = set(map(tuple, contracts_of(path_a)))
    cb = set(map(tuple, contracts_of(path_b)))
    only_a = sorted(ca - cb)
    only_b = sorted(cb - ca)
    return {
        "identical": not (only_a or only_b),
        "distinguishing": [
            {"only_in": "before", "constraints": sorted(c), "result": r}
            for c, r in only_a
        ] + [

            {"only_in": "after", "constraints": sorted(c), "result": r}
            for c, r in only_b
        ],
    }


def verify_patch(before_path: str, after_path: str, claim: str = "equivalent") -> dict:
    """verify_patch(before, after, claim) -> proof | counterexample.

    claim 'equivalent': identical contracts -> verified. Otherwise a
    distinguishing input is produced from the linear fragment of the
    differing path -- and confirmed: the witness must satisfy the differing
    path and fall outside every same-result path on the other side (an input
    where both sides return the same thing is not a counterexample; see
    m146).  When no confirmed witness exists -- opaque constraints, or the
    fragment -- the verdict is still refuted but the counterexample slot is
    honestly empty."""
    d = semantic_diff(before_path, after_path)
    if d["identical"]:
        return {"verified": True, "claim": claim, "counterexample": None,
                "distinguishing": []}
    sides = {"before": contracts_of(before_path),
             "after": contracts_of(after_path)}
    lb = LinearBackend()
    for entry in d["distinguishing"]:
        other = "after" if entry["only_in"] == "before" else "before"
        same_result = [cs for cs, r in sides[other]
                       if r == entry["result"]]
        atoms, opaque = [], False
        for c in entry["constraints"]:
            try:
                parse_atom(str(c))
                atoms.append(str(c))
            except LinearError:
                opaque = True  # cannot confirm a witness on a
        if opaque:             # path we cannot evaluate
            continue
        cand = _find_witness(lb, atoms, same_result)
        if cand is not None:
            return {"verified": False, "claim": claim,

    return None if indeterminate else False


def _find_witness(lb, atoms, same_result_paths, max_tries=32):
    """An input on the differing path that is provably not covered by any
    same-result path on the other side; None if none found (or unconfirmable)."""
    atoms = list(atoms)
    for _ in range(max_tries):
        model = lb.learn(atoms)
        if not model.feasible():
            return None
        vals = model.model()
        if not vals:
            return None
        cov = _covered(vals, same_result_paths)
        if cov is False:
            return vals
        if cov is None:
            return None                         # opaque: refuse to guess
        var, val = next(iter(vals.items()))     # covered: exclude this point
        atoms.append(f"(1*{var} != {val})")
    return None

"""Live semantic dependencies among functions, contracts, and invariants."""
from __future__ import annotations

import json
import hashlib
import os
from pathlib import Path

SCHEMA = "pegrex.semantic-dependency-graph.v1"


def _identity(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


class SemanticDependencyGraph:
    def __init__(self, memory) -> None:
        self.memory = memory
        self.nodes = {}
        self.edges = []
        self.revision = None

    def refresh(self) -> dict:
        """Implement refresh with the module's explicit API and failure semantics."""
        if self.memory.memory_identity is None:
            self.memory.refresh()
        old_nodes = self.nodes
        self.nodes, self.edges = {}, []
        for path, architecture in sorted(self.memory.architecture.items()):
            module = f"module:{path}"
            self._node(module, "module", path=path,
                       source_sha256=architecture["source_sha256"])
        for key, api in sorted(self.memory.apis.items()):
            self._node(key, "function", path=api["path"], function=api["function"],
                       function_sha256=api["function_sha256"], status=api["status"])
            module = f"module:{api['path']}"
            self._edge(module, key, "contains")
            for contract in api["contracts"]:
                contract_key = f"contract:{_identity(contract)}"
                invariant_key = f"invariant:{_identity(contract)}"

            self._node(contract_key, "contract", function=key,
                       constraints=contract["constraints"], outcome=contract["outcome"])
            self._node(invariant_key, "invariant", function=key,
                       invariant_kind="path-contract", status=api["status"])
            self._edge(key, contract_key, "defines")
            self._edge(contract_key, invariant_key, "witnesses")
        for dependency in api["dependencies"]:
            candidates = [candidate for candidate, row in self.memory.apis.items()
                          if candidate != key and (row["function"] == dependency or
                                                   row["function"].endswith("." + dependency))]
            for callee in sorted(candidates):
                self._edge(key, callee, "calls",
                           resolution="conservative" if len(candidates) > 1 else "resolved")
    for path, architecture in sorted(self.memory.architecture.items()):
        source = f"module:{path}"
        for imported in architecture["imports"]:
            for other in self.memory.architecture:
                module_name = Path(other).with_suffix("").as_posix().replace("/", ".")
                if imported == module_name or imported.endswith("." + Path(other).stem):
                    self._edge(source, f"module:{other}", "imports")
    self.revision = self.memory.memory_identity
    changed = sorted(key for key in set(self.nodes) | set(old_nodes)
                     if old_nodes.get(key) != self.nodes.get(key))
    impacted = sorted(set().union(*(self.impact(key) for key in changed))) if changed else []
    return {"schema": SCHEMA, "revision": self.revision, "changed": changed,
            "impacted": sorted(set(impacted + changed)), "nodes": len(self.nodes),
            "edges": len(self.edges), "unknowns": list(self.memory.limitations)}

def _node(self, key, kind, **metadata):
    self.nodes[key] = {"id": key, "kind": kind, **metadata}

def _edge(self, source, target, kind, **metadata):
    self.edges.append({"source": source, "target": target, "kind": kind, **metadata})

def _walk(self, node, *, reverse=False, max_depth=100) -> set[str]:
    if node not in self.nodes:
        return set()
    adjacency = {}
    for edge in self.edges:
        source, target = (edge["target"], edge["source"]) if reverse else (edge["source"], edge["target"])

        adjacency.setdefault(source, set()).add(target)
    seen, frontier, depth = set(), {node}, 0
    while frontier and depth < max_depth:
        following = set().union(*(adjacency.get(row, set()) for row in frontier)) - seen - {node}
        seen.update(following)
        frontier = following
        depth += 1
    return seen

def dependencies(self, node: str, *, max_depth=100) -> list[str]:
    """Implement dependencies with the module's explicit API and failure semantics."""
    return sorted(self._walk(node, max_depth=max_depth))

def impact(self, node: str, *, max_depth=100) -> list[str]:
    """Implement impact with the module's explicit API and failure semantics."""
    return sorted(self._walk(node, reverse=True, max_depth=max_depth))

def payload(self) -> dict:
    """Implement payload with the module's explicit API and failure semantics."""
    return {"schema": SCHEMA, "revision": self.revision,
            "nodes": [self.nodes[key] for key in sorted(self.nodes)],
            "edges": sorted(self.edges, key=lambda row: (row["source"], row["target"], row["kind"])),
            "unknowns": list(self.memory.limitations)}

def save(self, path: str | Path) -> None:
    """Implement save with the module's explicit API and failure semantics."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(self.payload(), sort_keys=True, indent=2) + "\n", encoding="utf-8")
    os.replace(temporary, path)

"""Shared, content-addressed source analysis sessions.

One session owns one normalized syntax tree.  Consumers are lazy and memoized;
persistent entries are addressed by source content, parser/analyzer versions,
and normalized configuration rather than path or mtime.  Legacy analyzer
functions remain available independently and retain their public result shapes.
"""
from __future__ import annotations

import hashlib
import json
import time
from typing import Any

from .cache import AnalysisCache
from .languages import get_language, normalize_language, parse_source
from .peg import Node

SESSION_VERSION = "shared-analysis-v1"


class AnalysisTimeout(TimeoutError):
    """A per-file analysis deadline expired; callers must report UNKNOWN."""


def _tree_data(value):
    if isinstance(value, Node):
        return {"tag": value.tag, "pos": value.pos, "endpos": value.endpos,
                "children": [_tree_data(child) for child in value.children]}
    if isinstance(value, list):
        return [_tree_data(child) for child in value]
    return value


def _tree_value(value):
    if isinstance(value, dict):
        return Node(value["tag"], value["pos"], value["endpos"],
                    [_tree_value(child) for child in value["children"]])
    if isinstance(value, list):
        return [_tree_value(child) for child in value]

    if self._deadline is not None and time.monotonic() > self._deadline:
        raise AnalysisTimeout(
            f"{self.path or '<source>'}: analysis exceeded {self.timeout_ms}ms")

def _version(self) -> dict:
    return {"session": SESSION_VERSION, "parser": self.spec.parser_version}

def _config(self) -> dict:
    return {"language": self.language, "max_paths": self.max_paths,
            **self.configuration}

def _persistent(self, analyzers: tuple[str, ...], producer):
    self._check_deadline()
    if self.cache is not None:
        payload = self.cache.get(self.source, analyzers,
                                 version=self._version(), configuration=self._config())
        if payload is not None:
            self.cache_hits += 1
            return payload
    self.cache_misses += 1
    value = producer()
    self._check_deadline()
    if self.cache is not None:
        self.cache.put(self.source, analyzers, value,
                       version=self._version(), configuration=self._config())
    return value

@property
def tree(self):
    """The sole normalized parse for this source/configuration session.

    An optional repository-owned tree cache shares the immutable-by-
    convention normalized tree across sessions with identical content,
    parser identity, and configuration. Paths never enter its identity.
    """
    self._check_deadline()
    if "tree" not in self._values:
        identity = json.dumps(self._config(), sort_keys=True, separators=(",", ":"),
                              default=str)
        key = (self.digest, self.spec.parser, self.spec.parser_version,

                                            timeout_ms=self.timeout_ms)])
        self._values[key] = [(frozenset(guards), outcome) for guards, outcome in rows]
    return self._values[key]

@property
def call_graph(self):
    """Implement call graph with the module's explicit API and failure semantics."""
    self._check_deadline()
    if "call_graph" not in self._values:
        from .callgraph import CallGraph, build_call_graph

        def produce():
            """Implement produce with the module's explicit API and failure semantics."""
            graph = build_call_graph(self.source, self.language, tree=self.tree)
            return {"functions": {name: {"line": row["line"],
                                         "calls": sorted(row["calls"])}
                                  for name, row in graph.functions.items()},
                    "edges": sorted(map(list, graph.edges))}

        data = self._persistent(("callgraph", SESSION_VERSION), produce)
        graph = CallGraph()
        graph.functions = {name: {"line": row["line"], "calls": set(row["calls"])}
                           for name, row in data["functions"].items()}
        graph.edges = {tuple(edge) for edge in data["edges"]}
        self._values["call_graph"] = graph
    return self._values["call_graph"]

@property
def complexity(self):
    """Implement complexity with the module's explicit API and failure semantics."""
    self._check_deadline()
    if "complexity" not in self._values:
        from .cognitive import cognitive_complexity
        self._values["complexity"] = self._persistent(
            ("complexity", SESSION_VERSION),
            lambda: cognitive_complexity(self.source, self.language, tree=self.tree))
    return self._values["complexity"]

@property
def security(self):

    """SAST and taint findings over the shared tree."""
    self._check_deadline()
    if "security" not in self._values:
        from tools.secaudit import audit_source
        self._values["security"] = self._persistent(
            ("sast", "taint", SESSION_VERSION),
            lambda: audit_source(self.source, self.language, tree=self.tree))
    return self._values["security"]

def synthesize_tests(self, coverage_lines, function_name: str, unroll: int = 2):
    """Synthesize tests from the session CFG without another source parse."""
    self._check_deadline()
    key = ("tests", tuple(sorted(coverage_lines)), function_name, unroll)
    if key not in self._values:
        from .testsynth import synthesize_tests
        cfg, condition = self.cfg(function_name)
        self._values[key] = synthesize_tests(
            cfg, condition, set(coverage_lines), function_name, unroll=unroll)
    return self._values[key]

def analyze(self, analyzers=("contracts", "call_graph", "complexity", "security")) -> dict:
    """Run selected consumers and expose per-analyzer resource UNKNOWNs."""
    results = {}
    for name in analyzers:
        try:
            value = self.contracts() if name == "contracts" else getattr(self, name)
            if name == "contracts":
                value = [[sorted(map(str, guards)), outcome] for guards, outcome in value]
            elif name == "call_graph":
                value = {"functions": {key: {"line": row["line"],
                                             "calls": sorted(row["calls"])}
                                       for key, row in value.functions.items()},
                         "edges": sorted(map(list, value.edges))}
            results[name] = {"status": "ok", "data": value}
        except AnalysisTimeout as exc:
            results[name] = {"status": "unknown", "reason": str(exc),
                             "resource": "per-file-timeout"}
        except Exception as exc:
            from .paths import PathExplosion
            if not isinstance(exc, PathExplosion):

            raise
        results[name] = {"status": "unknown", "reason": str(exc),
                         "resource": "path-count-cap"}
return {"schema": "pegrex.analysis-session.v1", "language": self.language,
        "source_sha256": self.digest, "results": results}

"slsa - SLSA-style attestations."

import hashlib
import os

from .attest import hmac_sign, hmac_verify


class SigstoreUnavailableError(RuntimeError):
    pass


def hash_materials(paths):
    """Implement hash materials with the module's explicit API and failure semantics."""
    out = {}
    for p in paths:
        with open(p, "rb") as f:
            out[p] = hashlib.sha256(f.read()).hexdigest()
    return out


def attest(builder, command, cert_bundle, material_paths, key):
    """Build + sign a provenance statement."""
    prov = {
        "_type": "https://slsa.dev/provenance/v1",
        "builder": {"id": builder},
        "command": command,
        "cert_bundle": cert_bundle,
        "materials": hash_materials(material_paths),
    }
    sig = hmac_sign(prov, key)
    return {"provenance": prov, "signature": sig,
            "cert_bundle": cert_bundle}


def verify(attestation, key):
    """Re-check material hashes and the signature. Refusal names why."""
    prov = attestation.get("provenance")
    sig = attestation.get("signature")
    if not prov or not sig:

        return {"ok": False, "reason": "incomplete attestation"}
    for path, digest in prov.get("materials", {}).items():
        if not os.path.exists(path):
            return {"ok": False, "reason": f"material missing: {path}"}
        with open(path, "rb") as f:
            actual = hashlib.sha256(f.read()).hexdigest()
        if actual != digest:
            return {"ok": False, "reason": f"material tampered: {path}"}
    if not hmac_verify(prov, key, sig):
        return {"ok": False, "reason": "signature mismatch"}
    return {"ok": True, "materials": len(prov["materials"]),
            "builder": prov["builder"]["id"]}


def publish_sigstore(attestation, token=None):
    """Implement publish sigstore with the module's explicit API and failure semantics."""
    if not token:
        raise SigstoreUnavailableError(
            "slsa: Sigstore/Rekor publish needs credentials and network -- "
            "refusing to pretend publication happened")
    raise SigstoreUnavailableError(
        "slsa: network unavailable in this environment; attestation stays "
        "local (signature remains verifiable offline)")


def slsa_level(attestation):
    """Implement slsa level with the module's explicit API and failure semantics."""
    if not attestation.get("signature"):
        return "L0 (unsigned)"
    return "L2-equivalent (signed build provenance; hermeticity not claimed)"

"""Separated Solidity source, EVM bytecode, formal, and local-test evidence."""
from __future__ import annotations

import hashlib
import re

SCHEMA = "pegrex.smart-contract-evidence.v1"


def check_contract_source(source) -> dict:
    """Run explicitly heuristic source checks; absence is not a proof."""
    findings = []
    try:
        if re.search(r"\btx\s*\.\s*origin\b", source):
            findings.append({"id": "SOL-TX-ORIGIN", "evidence": "tx.origin authorization requires review"})
        if re.search(r"\bselfdestruct\s*\(", source):
            findings.append({"id": "SOL-SELFDESTRUCT", "evidence": "selfdestruct is present"})
        lines = source.splitlines()
        for index, line in enumerate(lines):
            if re.search(r"\.(?:call|delegatecall|send|transfer)\s*(?:\{|\()", line):
                following = "\n".join(lines[index + 1:index + 5])
                if not re.search(r"\w+\s*(?:=|\+=|-=|\+\+|--)", following):
                    findings.append({"id": "SOL-EXTERNAL-CALL-ORDER", "line": index + 1,
                                     "evidence": "external call without a following state update in the local source window"})
        return {"status": "completed", "verdict": "refuted" if findings else "unknown",
                "findings": findings, "source_sha256": hashlib.sha256(source.encode()).hexdigest(),
                "unknowns": [] if findings else ["source-pattern absence is not a formal safety proof"],
                "scope": "source-level heuristic checks only"}
    except Exception as error:
        return {"status": "unknown", "verdict": "unknown", "findings": [],
                "unknowns": [f"source analysis failed: {error}"]}


def check_evm_bytecode(bytecode) -> dict:
    """Disassemble PUSH widths correctly before checking opcode presence."""
    try:
        text = bytecode.removeprefix("0x")
        if len(text) % 2 or not text or any(character not in "0123456789abcdefABCDEF" for character in text):
            raise ValueError("bytecode must be nonempty, even-length hexadecimal")
        data = bytes.fromhex(text)

        opcodes, push_data = [], []
        pc = 0
        while pc < len(data):
            opcode = data[pc]
            opcodes.append({"pc": pc, "opcode": opcode})
            pc += 1
            if 0x60 <= opcode <= 0x7f:
                width = opcode - 0x5f
                if pc + width > len(data):
                    raise ValueError("truncated PUSH immediate")
                push_data.append({"pc": pc, "bytes": width})
                pc += width
        names = {0xf1: "CALL", 0xf2: "CALLCODE", 0xf4: "DELEGATECALL", 0xff: "SELFDESTRUCT"}
        findings = [{"id": "EVM-" + names[row["opcode"]], "pc": row["pc"]}
                    for row in opcodes if row["opcode"] in names]
        return {"status": "completed", "verdict": "refuted" if findings else "unknown",
                "findings": findings, "instructions": len(opcodes), "push_data": push_data,
                "bytecode_sha256": hashlib.sha256(data).hexdigest(),
                "unknowns": [] if findings else ["opcode absence is not a formal bytecode safety proof"],
                "scope": "bytecode disassembly and selected opcode checks"}
    except Exception as error:
        return {"status": "unknown", "verdict": "unknown", "findings": [],
                "unknowns": [f"bytecode analysis failed: {error}"]}


def evaluate_formal_claims(claims) -> dict:
    """Implement evaluate formal claims with the module's explicit API and failure semantics."""
    rows = []
    for claim in claims:
        verdict = claim.get("verdict", "unknown")
        if verdict == "proved" and not claim.get("proof"):
            verdict = "unknown"
        if verdict == "refuted" and not (claim.get("counterexample") or {}).get("confirmed"):
            verdict = "unknown"
        if verdict not in {"proved", "refuted", "unknown"}:
            verdict = "unknown"
        rows.append({"id": claim.get("id"), "statement": claim.get("statement"),
                     "verdict": verdict, "proof": claim.get("proof"),
                     "counterexample": claim.get("counterexample"),
                     "unknowns": [] if verdict != "unknown" else ["formal claim lacks independently checkable evidence"]})

    return {"verdict": "refuted" if any(row["verdict"] == "refuted" for row in rows)
                       else "unknown" if not rows or any(row["verdict"] == "unknown" for row in rows)
                       else "proved", "claims": rows,
            "scope": "declared claims only; not source or bytecode agreement"}


def run_local_evm_tests(bytecode, tests, runner=None) -> dict:
    """Use a caller-supplied local EVM; never substitute a remote node."""
    if runner is None:
        return {"status": "unknown", "verdict": "unknown", "executed": False,
                "results": [], "unknowns": ["local EVM runner unavailable"]}
    try:
        report = runner(bytecode, list(tests))
        if not isinstance(report, dict) or not report.get("executed") or not report.get("local"):
            raise ValueError("runner did not confirm local EVM execution")
        results = list(report.get("results") or [])
        expected = len(tests)
        if len(results) != expected:
            raise ValueError("local EVM result count differs from test count")
        failed = [row for row in results if row.get("passed") is False]
        incomplete = [row for row in results if row.get("passed") not in {True, False}]
        verdict = "refuted" if failed else "unknown" if incomplete or not results else "proved"
        return {"status": "completed", "verdict": verdict, "executed": True,
                "local": True, "backend": report.get("backend", "local-evm"),
                "results": results, "unknowns": [] if results and not incomplete else ["no complete local EVM test evidence"],
                "scope": "supplied tests on a local EVM only"}
    except Exception as error:
        return {"status": "unknown", "verdict": "unknown", "executed": False,
                "results": [], "unknowns": [f"local EVM execution failed: {error}"]}


def analyze_smart_contract(*, source=None, bytecode=None, formal_claims=(),
                           local_tests=(), evm_runner=None) -> dict:
    """Implement analyze smart contract with the module's explicit API and failure semantics."""
    sections = {
        "source": check_contract_source(source) if source is not None else {
            "status": "unknown", "verdict": "unknown", "unknowns": ["source not supplied"]},
        "bytecode": check_evm_bytecode(bytecode) if bytecode is not None else {
            "status": "unknown", "verdict": "unknown", "unknowns": ["bytecode not supplied"]},
        "formal": evaluate_formal_claims(formal_claims),

    "local_evm": run_local_evm_tests(bytecode, local_tests, evm_runner),
}
verdict = ("refuted" if any(row.get("verdict") == "refuted" for row in sections.values())
           else "unknown")
unknowns = [f"{name}: {reason}" for name, row in sections.items()
            for reason in row.get("unknowns", [])]
return {"schema": SCHEMA, "schema_version": 1, "verdict": verdict,
        "sections": sections, "unknowns": unknowns,
        "scope": "evidence layers remain separate; no deployment or legal-safety conclusion"}

"""
smt 

║  Self-contained solver for the path-constraint fragment (QF_LIA-ish): 
║  learn(atoms) -> model; entails(model, guard); feasible(model). 
║  Swap in z3 behind the Backend protocol when guards outgrow the fragment."""

from __future__ import annotations

import re
from dataclasses import dataclass, field

_ATOM = re.compile(r"^\((?P<var>[A-Za-z_]\w*)\s*(?P<op><=|>=|<|>|=)\s*(?P<k>-?\d+)\)$")
_NEG = re.compile(r"^\(not\s+\((?P<var>[A-Za-z_]\w*)\s*(?P<op><=|>=|<|>|=)\s*(?P<k>-?\d+)\)\)$")
_NEGATE = {"=": "!=", "<": ">=", "<=": ">", ">": "<=", ">=": "<"}


def _parse_atom(s: str):
    s = s.strip()
    if (m := _NEG.match(s)):
        return (_NEGATE[m.group("op")], m.group("var"), int(m.group("k")))
    if (m := _ATOM.match(s)):
        return (m.group("op"), m.group("var"), int(m.group("k")))
    return None


@dataclass
class Model:
    """Bounds model: var -> [lo, lo_inc, hi, hi_inc, neq]."""
    bounds: dict = field(default_factory=dict)

    def _entry(self, var: str):
        return self.bounds.setdefault(var, [None, True, None, True, set()])

    def add_atom(self, op: str, var: str, k: int) -> None:
        """add atom(op, var, k): see module docstring."""
        e = self._entry(var)
        if op == "=":
            e[0], e[1], e[2], e[3] = k, True, k, True
        elif op == "!=":

            e[4].add(k)
        elif op in ("<", "<="):
            inc = op == "<="
            if e[2] is None or k < e[2] or (k == e[2] and e[3] and not inc):
                e[2], e[3] = k, inc
        else:  # >, >=
            inc = op == ">="
            if e[0] is None or k > e[0] or (k == e[0] and e[1] and not inc):
                e[0], e[1] = k, inc

    def feasible(self) -> bool:
        """Implement feasible with the module's explicit API and failure semantics."""
        for lo, li, hi, hi_inc, neq in self.bounds.values():
            if lo is not None and hi is not None:
                if lo > hi or (lo == hi and not (li and hi_inc)):
                    return False
                if lo == hi and lo in neq:
                    return False
        return True


def learn(atoms) -> Model:
    """Implement learn with the module's explicit API and failure semantics."""
    m = Model()
    for a in atoms:
        if (p := _parse_atom(str(a))):
            m.add_atom(*p)
    return m


def _entails_atom(m: Model, op: str, var: str, k: int) -> bool:
    lo, li, hi, hi_inc, neq = m.bounds.get(var, [None, True, None, True, set()])
    match op:
        case "=":
            return (lo is not None and hi is not None and lo == hi == k
                    and li and hi_inc and k not in neq)
        case "!=":
            if lo is not None and hi is not None and lo == hi:
                return lo != k or k in neq
            if lo is not None and (k < lo or (k == lo and not li)):

                return True
            if hi is not None and (k > hi or (k == hi and not hi_inc)):
                return True
            return False
        case "<":
            return hi is not None and (hi < k or (hi == k and not hi_inc))
        case "<=":
            return hi is not None and (hi < k or (hi == k and hi_inc))
        case ">":
            return lo is not None and (lo > k or (lo == k and not li))
        case ">=":
            return lo is not None and (lo > k or (lo == k and li))
    return False


def _split_top(s: str) -> list[str]:
    parts, depth, cur = [], 0, ""
    for ch in s:
        depth += (ch == "(") - (ch == ")")
        if ch == " " and depth == 0:
            if cur:
                parts.append(cur)
                cur = ""
        else:
            cur += ch
    return parts + ([cur] if cur else [])


def entails(model: Model, guard) -> bool:
    """True if every model of the learned atoms satisfies the guard."""
    s = str(guard).strip()
    if s.startswith("(and"):
        return all(entails(model, p) for p in _split_top(s[4:-1]))
    if s.startswith("(or"):
        return any(entails(model, p) for p in _split_top(s[3:-1]))
    if s.startswith("(not"):
        inner = s[4:-1].strip()
        if (p := _parse_atom(inner)) and p[0] in ("<", "<=", ">", ">="):
            return _entails_atom(model, _NEGATE[p[0]], p[1], p[2])
        if p and p[0] == "=":

            return _entails_atom(model, "!=", p[1], p[2])
        return False
    return _entails_atom(model, *_parse_atom(s)) if _parse_atom(s) else False


# ── backend seam
class Backend:
    """The only surface specgen/idioms consume. Swap in z3 by subclassing."""

    def learn(self, atoms):
        """Implement learn with the module's explicit API and failure semantics."""
        return learn(atoms)

    def entails(self, model, guard):
        """Implement entails with the module's explicit API and failure semantics."""
        return entails(model, guard)

    def feasible(self, model):
        """Implement feasible with the module's explicit API and failure semantics."""
        return model.feasible()


_default = Backend()


def get_backend() -> Backend:
    """Implement get backend with the module's explicit API and failure semantics."""
    return _default


def set_backend(backend: Backend) -> None:
    """Implement set backend with the module's explicit API and failure semantics."""
    global _default
    _default = backend




# ── auto-escalation: fragment detection + optional z3
def _fragment_exceeded(atoms) -> bool:

    """True if atoms leave the single-variable linear fragment
    (multi-variable atoms or non-constant right-hand sides)."""
    import re as _re
    for a in map(str, atoms):
        vars_ = set(_re.findall(r"[A-Za-z_]\w*(?=@|\b)", a))
        vars_ = {v for v in vars_ if not v.isdigit()
                 and v not in ("not", "and", "or")}
        nums = _re.findall(r"-?\d+", a)
        if len(vars_) > 1 or (vars_ and not nums):
            return True
    return False


def auto_feasible(atoms) -> bool | None:
    """Return True/False, or None when no installed backend can decide.

    The bounds engine handles its exact single-variable fragment. Larger
    linear atoms go to Z3; a missing solver or an incomplete translation is
    UNKNOWN, never a best-effort answer with unsupported atoms discarded.
    """
    atoms = list(atoms)
    if not _fragment_exceeded(atoms):
        if any(_parse_atom(str(a)) is None for a in atoms):
            return None
        return learn(atoms).feasible()
    try:
        import z3
    except ImportError:
        return None
    try:
        solver = z3.Solver()
        for atom in atoms:
            solver.add(_to_z3(z3, str(atom)))
        verdict = solver.check()
    except (ValueError, TypeError, z3.Z3Exception):
        return None
    if verdict == z3.sat:
        return True
    if verdict == z3.unsat:
        return False

    return None


def _to_z3(z3, s):
    s = s.strip()
    m = _ATOM.match(s)
    if m:
        ops = {"=": lambda a, b: a == b, "!=": lambda a, b: a != b,
               "<": lambda a, b: a < b, "<=": lambda a, b: a <= b,
               ">": lambda a, b: a > b, ">=": lambda a, b: a >= b}
        return ops[m.group("op")](z3.Int(m.group("var")),
                                  int(m.group("k")))
    if (m := _NEG.match(s)):
        inner = f"({m.group('var')} {m.group('op')} {m.group('k')})"
        return z3.Not(_to_z3(z3, inner))
    simple = re.match(r"^\(\s*([A-Za-z_]\w*|-?\d+)\s*(<=|>=|<|>|=|!=)\s*"
                      r"([A-Za-z_]\w*|-?\d+)\s*\)$", s)
    if simple:
        def operand(text):
            """Implement operand with the module's explicit API and failure semantics."""
            return z3.IntVal(int(text)) if text.lstrip("-").isdigit() else z3.Int(text)
        left, right = operand(simple.group(1)), operand(simple.group(3))
        ops = {"=": lambda a, b: a == b, "!=": lambda a, b: a != b,
               "<": lambda a, b: a < b, "<=": lambda a, b: a <= b,
               ">": lambda a, b: a > b, ">=": lambda a, b: a >= b}
        return ops[simple.group(2)](left, right)
    # Multi-variable linear atoms use the same parser as the FM backend.
    # Variables remain integers; rational coefficients/bounds are exact.
    from .linsolve import LinearError, parse_atom
    try:
        atom = parse_atom(s)
    except LinearError as exc:
        raise ValueError(f"cannot translate: {s!r}") from exc
    def exact(value):
        # Z3 5.x removed RationalVal from the Python API. Integer numerator
        # and denominator division preserves the exact rational semantics on
        # both older and newer supported releases.
        """Implement exact with the module's explicit API and failure semantics."""
        numerator = z3.IntVal(value.numerator)
        if value.denominator == 1:

            return numerator
        # IntVal / IntVal is integer division in Z3 5.x; explicitly use a
        # real numerator so 1/2 cannot silently collapse to zero.
        return z3.RealVal(value.numerator) / value.denominator

    expr = sum((z3.Int(var) * exact(coeff)
                for var, coeff in atom.coeffs), z3.IntVal(0))
    bound = exact(atom.k)
    ops = {"=": lambda a, b: a == b, "!=": lambda a, b: a != b,
           "<": lambda a, b: a < b, "<=": lambda a, b: a <= b,
           ">": lambda a, b: a > b, ">=": lambda a, b: a >= b}
    return ops[atom.op](expr, bound)


# ── cross-check: bounds backend vs z3 on the same queries
class SMTCrosscheckError(ValueError):
    """Refusal: the cross-check itself cannot be performed honestly."""


def _z3():
    try:
        import z3
        return z3
    except ImportError as e:
        raise SMTCrosscheckError(
            "z3 not installed; refusing to cross-check silently "
            "(pip install z3-solver)") from e


def _guard_to_z3(z3, s):
    """Guard syntax: atom | (not atom) | (and ...) | (or ...)."""
    s = s.strip()
    if s.startswith("(and"):
        return z3.And(*[_guard_to_z3(z3, p) for p in _split_top(s[4:-1])])
    if s.startswith("(or"):
        return z3.Or(*[_guard_to_z3(z3, p) for p in _split_top(s[3:-1])])
    if s.startswith("(not"):
        return z3.Not(_guard_to_z3(z3, s[4:-1].strip()))
    return _to_z3(z3, s)

bad = [a for a in atoms if _parse_atom(a) is None]
if bad:
    return {"agree": None, "queries": 0,
            "refusal": f"atom outside cross-check fragment: {bad[0]!r}"}
try:
    z3 = _z3()
except SMTCrosscheckError as e:
    return {"agree": None, "queries": 0, "refusal": str(e)}
backend = get_backend()
model = backend.learn(atoms)
if guards is None:
    guards = _gen_guards(atoms, n, seed)
witnesses = []
for g in guards:
    b = backend.entails(model, g)
    z = _z3_entails(z3, atoms, g)
    if b != z:
        witnesses.append({"guard": g, "backend": b, "z3": z})
bf, zf = backend.feasible(model), _z3_feasible(z3, atoms)
if bf != zf:
    witnesses.append({"guard": "<feasibility>", "backend": bf, "z3": zf})
return {"queries": len(guards) + 1, "agree": not witnesses,
        "witnesses": witnesses, "refusal": None}

"""
specgen

║  The AI debugging interface: one AST in, AgentReport out. 
