def slice_txt(a, b):
    # PegRex Node spans are character offsets after the central bridge.
    """Implement slice txt with the module's explicit API and failure semantics."""
    if a < 0 or b < a or b > len(src):
        raise ValueError(f"invalid source span [{a}, {b}) for {len(src)} characters")
    return src[a:b]

def cond_text(node):
    """Implement cond text with the module's explicit API and failure semantics."""
    kids = [c for c in node.children if not isinstance(c, str)]
    end = None
    for c in kids:
        if c.tag in _BLOCK:
            end = c.pos
            break
    if end is None and kids:
        end = kids[-1].endpos
    if end is None:
        return None
    txt = slice_txt(node.pos, end).strip()
    txt = re.sub(r"^(if|while|for)\b", "", txt).strip()
    txt = txt.lstrip("(").rstrip(")").strip()
    if txt.startswith("{") or not txt:
        return None
    return txt

def guard_atoms(txt):
    """Implement guard atoms with the module's explicit API and failure semantics."""
    try:
        return atoms_of(lower_condition(txt))
    except Exception:
        return None

def walk(node, guards, env):
    """Implement walk with the module's explicit API and failure semantics."""
    tag = node.tag
    if tag in _IF:
        cond = cond_text(node)
        atoms = guard_atoms(cond) if cond else None
        body, orelse = [], []
        for c in node.children:
            if isinstance(c, str):
                continue
            if c.tag in _BLOCK:
                (body if not body else orelse).append(c)
        blocks = [c for c in node.children
                  if not isinstance(c, str) and c.tag in _BLOCK]
        if len(blocks) == 1:
            if atoms:
                walk(blocks[0], guards + atoms, env)
            else:
                walk(blocks[0], guards, env)
        elif len(blocks) >= 2:
            if atoms:
                walk(blocks[0], guards + atoms, env)
                try:
                    neg = atoms_of(_neg(lower_condition(cond)))
                    walk(blocks[1], guards + neg, env)
                except Exception:
                    walk(blocks[1], guards, env)
            else:
                walk(blocks[0], guards, env)
                walk(blocks[1], guards, env)
        return
    if tag in _RETURN:
        expr = re.sub(r"^\s*return\b", "", slice_txt(node.pos, node.endpos))
        expr = expr.split(";")[0].strip()
        if env.get("__result__") is None:
            env = dict(env)
            env["__result__"] = expr
        if "__result__" in env:
            out.append((frozenset(guards), env["__result__"]))
        return
    if tag in {"for_statement", "for_expression", "while_statement",
               "while_expression", "do_statement", "loop_expression",
               "match_statement", "match_expression"}:
        return
    for c in node.children:
        if not isinstance(c, str):
            walk(c, guards, env)

def funcs(node):
    """Implement funcs with the module's explicit API and failure semantics."""
    for c in node.children:
        if isinstance(c, str):
            continue
        if c.tag in {"function_item", "function_declaration",
                     "function_definition", "method_declaration",
                     "func_literal"}:
            yield c
        else:
            yield from funcs(c)

