def _binop(op, a, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    return {"<": a < b, "<=": a <= b, ">": a > b,
            ">=": a >= b, "==": a == b, "!=": a != b}[op]


def compile_fn(src):
    """Python source (single function) -> (code, branches).

    code: list of (op, arg). branches: {pc_of_guard: condition-source}
    for concolic integration."""
