        model = backend.learn(atoms)
        guard = _atom_text(rng)
        verdict = backend.entails_with_status(model, guard)["status"]
        oracle = _z3_entails(z3, atoms, guard)
        if verdict == "entailed":
            proofs += 1
            assert oracle, {"atoms": atoms, "guard": guard}
